(window.WCD=window.WCD||[]).push(["bolides",[["Q620223",1,"pilote","Aleix Espargaró","PC","Aleix Espargaró Villà, né le 30 juillet 1989 à Granollers, est un pilote motocycliste espagnol. Son frère cadet, Pol Espargaró est aussi pilote de moto en MotoGP chez GASGAS Factory Racing Tech3. Depuis 2012, il est titulaire en MotoGP et pilote en 2022 chez Aprilia Racing. En 2024, il annonce sa retraite à Barcelone.","Aleix Espargaró Villà, né le 30 juillet 1989 à Granollers, est un pilote motocycliste espagnol.","fr:Aleix_Espargaró","c:3/38/Aleix_Espargaro_at_the_2022_San_Marino_Grand_Prix_at_Misano.jpg",{"cats":["bolides","moto"]}],["Q355033",2,"pilote","Andrea Dovizioso","R","Andrea Dovizioso, né le 23 mars 1986 à Forlimpopoli, est un pilote de vitesse moto italien.",null,"fr:Andrea_Dovizioso","c:c/cc/Andrea_Dovizioso_talks_to_media.jpg",{"cats":["bolides","moto"]}],["Q494147",3,"pilote","Andrea Iannone","PC","Andrea Iannone est un pilote de vitesse moto italien, né le 9 août 1989 à Vasto, dans la province de Chieti. Il est surnommé The Maniac Joe par de nombreux observateurs, en référence à son style de pilotage agressif.","Andrea Iannone est un pilote de vitesse moto italien, né le 9 août 1989 à Vasto, dans la province de Chieti.","fr:Andrea_Iannone","c:b/bf/Andrea_Iannone.jpg",{"cats":["bolides","moto"]}],["Q4775518",4,"pilote","Antoine Méo","C","Antoine Méo, né le 29 août 1984 à Digne-les-Bains, est un pilote de motocross, enduro, supercross et rallye-raid français. Il a été cinq fois champion du monde d'enduro de 2010 à 2015 et quatre fois champion du monde par équipe aux ISDE de 2009 à 2013.",112,"fr:Antoine_Méo","c:7/79/Antonie_Meo_WEC_Italy_2010.jpg",{"cats":["bolides","moto"]}],["Q726321",5,"pilote","Barry Sheene","R","Barry Sheene, né le 11 septembre 1950 à Londres et mort le 10 mars 2003 dans le Queensland, est un pilote motocycliste britannique, vainqueur de plusieurs championnats britanniques et mondiaux de moto de vitesse.",118,"fr:Barry_Sheene","c:b/b8/Barry_Sheene_winner.jpg",{"cats":["bolides","moto"]}],["Q552647",6,"pilote","Cal Crutchlow","C","Calvin « Cal » Crutchlow, né le 29 octobre 1985 à Coventry est un pilote de Grand Prix moto.",null,"fr:Cal_Crutchlow","c:5/50/Crutchlow_COTA_2015.jpg",{"cats":["bolides","moto"]}],["Q313563",7,"pilote","Casey Stoner","R","Casey Stoner, né le 16 octobre 1985 à Southport, Australie, est un ancien pilote de vitesse moto australien, double champion du monde MotoGP en 2007 et en 2011. Il porte le numéro 27.",115,"fr:Casey_Stoner","c:f/f0/Casey_Stoner_2010_Phillip_Island_1.jpg",{"cats":["bolides","moto"]}],["Q1081702",8,"pilote","Christian Sarron","C","Christian Sarron, né le 27 mars 1955 à Riom, est un pilote de vitesse moto français. Il est titré champion du monde catégorie 250 cm3 en 1984 après avoir été vice-champion en 1983.","Christian Sarron, né le 27 mars 1955 à Riom, est un pilote de vitesse moto français.","fr:Christian_Sarron","c:9/9a/Christian_Sarron%2C_motard.jpg",{"cats":["bolides","moto"]}],["Q382225",9,"pilote","Colin Edwards","C","Colin Edwards, né le 27 février 1974 à Houston, est un pilote de vitesse moto américain, double champion du monde Superbike en 2000 et 2002 au guidon d'une Honda VTR 1000 RC51.",113,"fr:Colin_Edwards","c:2/2e/ColinEdwards.JPG",{"cats":["bolides","moto"]}],["Q523864",10,"pilote","Cyril Despres","C","Cyril Despres, né le 24 janvier 1974 à Nemours, est un pilote moto puis auto français, pratiquant principalement le rallye-raid. Il a remporté cinq fois le Rallye Dakar moto entre 2005 et 2013.",115,"fr:Cyril_Despres","c:8/82/Cyrildespres.jpg",{"cats":["bolides","moto"]}],["Q472332",11,"pilote","Daijirō Katō","PC","Daijirō Katō, né le 4 juillet 1976 à Saitama et mort le 20 avril 2003 à Suzuka, est un pilote de vitesse moto japonais. Lors de la saison 2001, il décroche le titre de champion du monde catégorie 250 cm3 en remportant onze Grands Prix.","Daijirō Katō, né le 4 juillet 1976 à Saitama et mort le 20 avril 2003 à Suzuka, est un pilote de vitesse moto japonais.","fr:Daijirō_Katō","c:1/1b/Daijiro_Kato_2003_Japanese_GP.jpg",{"cats":["bolides","moto"]}],["Q313959",12,"pilote","Daniel Pedrosa","R","Daniel « Dani » Pedrosa, né le 29 septembre 1985 à Sabadell, province de Barcelone, est un pilote de vitesse moto espagnol. Il est champion du monde 125 cm3, double champion du monde 250 cm3 et a couru en MotoGP de 2006 à 2024.",113,"fr:Daniel_Pedrosa","c:8/88/Dani_Pedrosa_2018.jpg",{"cats":["bolides","moto"]}],["Q345231",13,"pilote","Evel Knievel","L","Evel Knievel, de son vrai nom Robert Craig Knievel, Jr., né à Butte le 17 octobre 1938 et mort à Clearwater le 30 novembre 2007, est un motard cascadeur américain. Il est le père de Robbie Knievel.",113,"fr:Evel_Knievel","c:c/cc/Evel_Knievel_c1974.jpg",{"cats":["bolides","moto"]}],["Q16635516",14,"pilote","Fabio Quartararo","R","Fabio Quartararo, né le 20 avril 1999 à Nice, est un pilote de vitesse moto français participant au championnat du monde MotoGP. Il est le premier Français champion du monde de cette catégorie.",114,"fr:Fabio_Quartararo","c:c/c4/Fabio_Quartararo_at_the_2023_Japanese_motorcycle_Grand_Prix.jpg",{"cats":["bolides","moto"]}],["Q15080981",15,"pilote","Francesco Bagnaia","E","Francesco Bagnaia, surnommé Pecco Bagnaia, né le 14 janvier 1997 à Turin, est un pilote de vitesse moto italien, champion du monde Moto2 en 2018 avec l'équipe Sky Racing Team VR46, et double champion du monde MotoGP en 2022 et 2023 avec l’équipe Ducati Lenovo Team.",112,"fr:Francesco_Bagnaia","c:d/dc/Pecco_Bagnaia_2021.jpg",{"cats":["bolides","moto"]}],["Q953029",16,"pilote","Freddie Spencer","C","Frederick Burdette Spencer Junior ou Freddie Spencer, né le 20 décembre 1961, surnommé « Fast Freddie », est un pilote de Grand Prix motocycliste américain, trois fois champion du monde.",118,"fr:Freddie_Spencer","c:f/f1/1985_Laguna_Seca_200_-_Freddie_Spencer_%28cropped%29.jpg"],["Q253450",17,"pilote","Giacomo Agostini","E","Giacomo Agostini est un pilote de vitesse moto dans les catégories 350 cm3, 500 cm3 et 750 cm3.",null,"fr:Giacomo_Agostini","c:b/bb/Giacomo_Agostini_2022.jpg",{"cats":["bolides","moto"]}],["Q320966",18,"pilote","Gábor Talmácsi","C","Gábor Talmácsi, né le 28 mai 1981 à Budapest, est un pilote de vitesse moto hongrois.",null,"fr:Gábor_Talmácsi","c:7/72/Gabor_Talmacsi-Aprilla-1.jpg",{"cats":["bolides","moto"]}],["Q2696702",19,"pilote","Jeremy McGrath","C","Jeremy McGrath, né le 19 novembre 1971 à San Francisco en Californie, est un pilote américain de moto-cross. Détenteur du plus grand palmarès du Supercross US, c'est aussi l'inventeur du Nac-Nac, une figure de moto-cross devenue un classique du genre.","Jeremy McGrath, né le 19 novembre 1971 à San Francisco en Californie, est un pilote américain de moto-cross.","fr:Jeremy_McGrath","c:3/35/JeremyMcGrathCrandon2009_%28cropped2%29.jpg",{"cats":["bolides","moto"]}],["Q1358228",20,"pilote","Joey Dunlop","PC","William Joseph Dunlop, dit \"Joey\", est un pilote moto de course sur route originaire de Ballymoney en Irlande du Nord. Avec 26 victoires au Tourist Trophy de l'île de Man, il fut le recordman du nombre de trophées pour cette épreuve, pour être ensuite dépassé par son neveu Michael Dunlop. Il a également gagné 24 fois le Grand Prix d'Ulster.","William Joseph Dunlop, dit \"Joey\", est un pilote moto de course sur route originaire de Ballymoney en Irlande du Nord.","fr:Joey_Dunlop","c:2/25/Joey_Dunlop.JPG",{"cats":["bolides","moto"]}],["Q221180",21,"pilote","Johann Zarco","R","Johann Zarco, né le 16 juillet 1990 à Cannes, est un pilote de vitesse moto français, double champion du monde Moto2 en 2015 et 2016.",119,"fr:Johann_Zarco","c:c/cb/Johann_Zarco_at_the_2022_San_Marino_Grand_Prix_at_Misano.jpg",{"cats":["bolides","moto"]}],["Q3153",22,"pilote","John Surtees","R","John Surtees est un ancien pilote motocycliste et automobile britannique, né le 11 février 1934 à Tatsfield dans le comté de Surrey en Angleterre et mort le 10 mars 2017 à Londres à l'âge de 83 ans.",115,"fr:John_Surtees","c:c/c3/John_Surtees.JPG",{"cats":["bolides","f1","moto"]}],["Q2736842",23,"pilote","Jonathan Rea","C","Jonathan Andrew Rea, né le 2 février 1987 à Ballymena en Irlande du Nord, est un pilote professionnel de vitesse moto britannique. Il court depuis 2008 en catégorie Superbike, dont il est sextuple champion du monde, en 2015, 2016, 2017, 2018, 2019 et 2020, et détenteur du record de victoires en carrière.",117,"fr:Jonathan_Rea","c:f/fe/Jonathan_Rea%2C_Donington_2016.jpg",{"cats":["bolides","moto"]}],["Q241112",24,"pilote","Jorge Lorenzo","R","Jorge Lorenzo, né le 4 mai 1987 à Palma, dans l'île de Majorque, est un pilote de vitesse moto espagnol, double champion du monde 250 cm3 et triple champion du monde MotoGP avec Yamaha en 2010, 2012 et 2015.",111,"fr:Jorge_Lorenzo","c:f/f1/Jorge_Lorenzo_2010_Indianapolis.jpg",{"cats":["bolides","moto"]}],["Q19729952",25,"pilote","Jorge Martín","L","Jorge Martín Almoguera, dit Jorge Martín, né le 29 janvier 1998 à Madrid, est un pilote de vitesse moto espagnol.",null,"fr:Jorge_Martín","c:2/2a/Jorge_Martin_at_the_2023_Japanese_motorcycle_Grand_Prix_%283x4_cropped%29.jpg",{"cats":["bolides","moto"]}],["Q77386",26,"pilote","Jutta Kleinschmidt","C","Jutta Kleinschmidt, née le 29 août 1962 à Cologne, est une pilote allemande de rallye-raid, résidant à Monaco. Elle est la seule femme à avoir remporté le rallye Dakar.","Jutta Kleinschmidt, née le 29 août 1962 à Cologne, est une pilote allemande de rallye-raid, résidant à Monaco.","fr:Jutta_Kleinschmidt","c:4/48/Kleinschmidt.jpg",{"cats":["bolides","moto"]}],["Q550266",27,"pilote","Kenny Roberts","C","Kenny Roberts, né le 31 décembre 1951 à Modesto en Californie, est un pilote de vitesse moto. Il fut le premier américain à remporter le championnat du monde de vitesse moto en catégorie 500 cm3.","Kenny Roberts, né le 31 décembre 1951 à Modesto en Californie, est un pilote de vitesse moto.","fr:Kenny_Roberts","c:3/38/Kenny_Roberts.jpg",{"cats":["bolides","moto"]}],["Q540522",28,"pilote","Kevin Schwantz","PC","Kevin Schwantz, né le 19 juin 1964 à Houston, est un pilote de vitesse moto américain.",null,"fr:Kevin_Schwantz","c:c/cc/Kevin_Schwantz_in_2010_cropped.JPG",{"cats":["bolides","moto"]}],["Q334382",29,"pilote","Loris Capirossi","PC","Loris Capirossi, surnommé Capirex, est un pilote de vitesse moto italien. Il est né le 4 avril 1973 à Castel San Pietro Terme. Son numéro fétiche est le 65.","Loris Capirossi, surnommé Capirex, est un pilote de vitesse moto italien.","fr:Loris_Capirossi","c:4/41/Loris_Capirossi.jpg",{"cats":["bolides","moto"]}],["Q510063",30,"pilote","Luis Salom","C","Luis Salom Horrach, né le 7 août 1991 à Palma de Mallorca et mort le 3 juin 2016 à Barcelone, à l'âge de 24 ans, lors des essais libres de Moto2 du Grand Prix de Catalogne, est un pilote de vitesse moto espagnol.",117,"fr:Luis_Salom","c:e/e2/Luis_Salom_2013_Catalunya.jpg",{"cats":["bolides","moto"]}],["Q40615",31,"pilote","Marc Márquez","M","Marc Márquez, né le 17 février 1993 à Cervera, est un pilote de vitesse moto espagnol.",null,"fr:Marc_Márquez","c:a/a7/Marc_Marquez_at_the_2026_Spanish_Grand_Prix_%28cropped%29.jpg",{"cats":["bolides","sports","moto"]}],["Q457818",32,"pilote","Marco Melandri","PC","Marco Melandri, né le 7 août 1982 à Ravenne, est un pilote de vitesse moto italien en catégorie MotoGP. Il a été champion du monde en 250 cm3 en 2002 avec Aprilia.","Marco Melandri, né le 7 août 1982 à Ravenne, est un pilote de vitesse moto italien en catégorie MotoGP.","fr:Marco_Melandri","c:5/57/2005_0512_Marco_Melandri.jpg",{"cats":["bolides","moto"]}],["Q193005",33,"pilote","Marco Simoncelli","L","Marco Simoncelli, né le 20 janvier 1987 à Cattolica, dans la province de Rimini, en Émilie-Romagne, et mort le 23 octobre 2011 à Sepang, en Malaisie, est un pilote de vitesse moto italien. Il est sacré champion du monde 250 cm3 en 2008.",113,"fr:Marco_Simoncelli","c:1/1f/Marco_Simoncelli_2009_Valencia.jpg",{"cats":["bolides","moto"]}],["Q176250",34,"pilote","Max Biaggi","R","Massimiliano Biaggi, dit Max, né le 26 juin 1971 à Rome, est un pilote de vitesse moto italien.",null,"fr:Max_Biaggi","c:1/10/Max_Biaggi_-_2007.JPG",{"cats":["bolides","moto"]}],["Q436025",35,"pilote","Michael Doohan","E","Michael « Mick » Doohan, né le 4 juin 1965 à Brisbane, est un ancien pilote de vitesse moto australien, quintuple champion du monde 500 cm3.",113,"fr:Michael_Doohan","c:5/55/Mick_Doohan_1990_Japanese_GP.jpg",{"cats":["bolides","moto"]}],["Q173147",36,"pilote","Mike Hailwood","PC","Mike Hailwood, né le 2 avril 1940 à Great Milton et mort le 23 mars 1981 à Birmingham, est un pilote moto puis automobile britannique.",110,"fr:Mike_Hailwood","c:f/f0/Mike_Hailwood.jpg",{"cats":["bolides","f1","moto"]}],["Q319553",37,"pilote","Nicky Hayden","R","Nicholas Patrick Hayden, dit « Nicky » Hayden, surnommé « l’enfant du Kentucky », né le 30 juillet 1981 à Owensboro et mort le 22 mai 2017 à Cesena, est un pilote de vitesse moto américain courant en championnat du monde FIM Superbike et auparavant en championnat du monde FIM MotoGP dont il fut couronné champion en 2006. Durant toute sa carrière, il arbora le numéro 69.",118,"fr:Nicky_Hayden","c:5/5c/Hayden_2016_%28cropped%29.jpg",{"cats":["bolides","moto"]}],["Q705985",38,"pilote","Olivier Jacque","C","Olivier Jacque, né le 29 août 1973 à Villerupt, est un pilote de vitesse moto français, connu pour avoir été champion du monde dans la catégorie 250 cm3 en 2000.",117,"fr:Olivier_Jacque","c:c/cb/Olivier_Jacque_1996_JapanGP.jpg"],["Q560534",39,"pilote","Pol Espargaró","C","Pol Espargaró Villà, né le 10 juin 1991 à Granollers, est un pilote de vitesse moto participant actuellement au Championnat du monde de vitesse moto. Il est double vainqueur des 8 Heures de Suzuka en 2015 et 2016",111,"fr:Pol_Espargaró","c:9/9a/Pol_Espargar%C3%B3_portrait_2022_%28cropped%29.jpg",{"cats":["bolides","moto"]}],["Q468477",40,"pilote","Randy de Puniet","C","Randy de Puniet, né le 14 février 1981 à Maisons-Laffitte, est un pilote de vitesse moto et d'endurance français.",null,"fr:Randy_de_Puniet","c:e/e8/DePuniet2026.jpg",{"cats":["bolides","moto"]}],["Q532073",41,"pilote","Ricky Carmichael","PC","Ricky Carmichael, né le 27 novembre 1979 à Clearwater en Floride, est un pilote américain de moto-cross.",null,"fr:Ricky_Carmichael","c:2/2f/RickyCarmichaelMay2007Key.jpg",{"cats":["bolides","moto"]}],["Q314254",42,"pilote","Shoya Tomizawa","C","Shōya Tomizawa, né le 10 décembre 1990 à Chiba, au Japon, et mort le 5 septembre 2010 à Riccione, était un pilote vitesse moto participant au grand prix moto dans les années 2000-2010. Il est mort à la suite d'un accident lors du Grand Prix de Saint-Marin de Moto2 en 2010. Il a réalisé sa première saison complète en 2009.",113,"fr:Shoya_Tomizawa","c:8/85/Qatar_Moto2_podium_2010.jpg",{"cats":["bolides","moto"]}],["Q312780",43,"pilote","Stéphane Peterhansel","C","Stéphane Peterhansel, dit Peter, né le 6 août 1965 à Échenoz-la-Méline, près de Vesoul, est un pilote de moto et auto de rallye-raid français. Il détient le record absolu de victoires au Rallye Dakar avec 14 victoires, 6 en catégorie moto avec Yamaha et 8 en auto, avec Mitsubishi, Mini, Peugeot.",117,"fr:Stéphane_Peterhansel","c:1/14/Dakar_2016_-_Conf%C3%A9rence_de_presse_-_20151118_-_060.jpg",{"cats":["bolides","moto"]}],["Q380326",44,"pilote","Toni Elías","C","Toni Elías, né le 26 mars 1983 à Manrèse, Catalogne, est un pilote de vitesse moto espagnol. Il a remporté le championnat du monde de Moto2 en 2010.","Toni Elías, né le 26 mars 1983 à Manrèse, Catalogne, est un pilote de vitesse moto espagnol.","fr:Toni_Elías","c:c/c6/Toni_elias_2007_malaysian_test.jpg",{"cats":["bolides","moto"]}],["Q169814",45,"pilote","Valentino Rossi","M","Valentino Rossi, né le 16 février 1979 à Urbino, est un pilote de vitesse moto et pilote automobile italien.",null,"fr:Valentino_Rossi","c:6/6c/Valentino_Rossi_2024_WEC_Fuji_2.jpg",{"cats":["bolides","sports","moto"]}],["Q464680",46,"pilote","Wayne Rainey","PC","Wayne Rainey, né le 23 octobre 1960 à Downey, est un pilote de vitesse moto américain.",null,"fr:Wayne_Rainey","c:4/46/Wayne_Rainey.jpg",{"cats":["bolides","moto"]}],["Q249447",47,"pilote","Álex Crivillé","C","Àlex Crivillé Tapias, né le 4 mars 1970 à Seva, est un pilote de vitesse moto espagnol, champion du monde des 500 cm3 en 1999.",117,"fr:Álex_Crivillé","c:9/9b/%C3%81lex_Crivill%C3%A9_2016.jpg",{"cats":["bolides","moto"]}],["Q250862",48,"pilote","Álvaro Bautista","PC","Álvaro Bautista, né le 21 novembre 1984 à Talavera de la Reina, est un pilote de vitesse moto espagnol. Il a évolué dans les catégories 125 cm3, 250 cm3 et MotoGP de 2002 à 2018. Il a notamment remporté le championnat 125 cm3 de 2006. À partir de 2019, il continue sa carrière dans le championnat du monde de Superbike. Il remporte le titre de champion du monde de Superbike en 2022 et 2023.","Álvaro Bautista, né le 21 novembre 1984 à Talavera de la Reina, est un pilote de vitesse moto espagnol.","fr:Álvaro_Bautista","c:2/2b/Alvaro_Bautista%2C_2022.jpg",{"cats":["bolides","moto"]}],["Q251846",49,"pilote","Ángel Nieto","PC","Ángel Nieto Roldán, né le 25 janvier 1947 à Zamora et mort le 3 août 2017 à Ibiza, est un pilote de vitesse moto espagnol.",112,"fr:Ángel_Nieto","c:9/9d/%C3%81ngel_Nieto.jpg",{"cats":["bolides","moto"]}],["Q45273105",50,"supercar","Aspark Owl","C","L'Aspark Owl est une hypercar électrique développée par le constructeur automobile japonais Aspark et produite en 50 exemplaires en Italie à partir de 2019, pour une livraison en mars 2020.",116,"fr:Aspark_Owl","c:9/90/Aspark_Owl%2C_Paris_Motor_Show_2018%2C_IMG_0661.jpg"],["Q750015",51,"supercar","Aston Martin One-77","PC","L’Aston Martin One-77 est une supercar développée par le constructeur automobile britannique Aston Martin. Dans un premier temps dénommée Aston Martin BDX, elle est finalement appelée One-77 lors de sa présentation, plutôt discrète, au Mondial de l'automobile de Paris 2008.","L’Aston Martin One-77 est une supercar développée par le constructeur automobile britannique Aston Martin.","fr:Aston_Martin_One-77","c:d/d8/Salon_Priv%C3%A9_London_2012_%287956675242%29.jpg"],["Q28402601",52,"supercar","Aston Martin Valkyrie","R","L'Aston Martin Valkyrie, connue également sous ses noms de code internes AM-RB 001 et Nebula, est une supercar produite par le constructeur automobile britannique Aston Martin à partir de novembre 2021. C'est un coupé deux-portes offrant deux places, dont le design est inspiré des monoplaces de la Formule 1. Le constructeur l'a créée en collaboration avec Red Bull Advanced Technologies.",119,"fr:Aston_Martin_Valkyrie","c:e/ec/Aston_Martin_Valkyrie_Verification_Prototype_001_Genf_2019_1Y7A5569.jpg"],["Q3271167",53,"supercar","Bentley Hunaudières","C","La Bentley Hunaudières est un concept-car construit par Bentley en 1999 pour le Salon international de l'automobile de Genève. Il est propulsé par un moteur W16 atmosphérique Volkswagen de 8,0 litres adapté et modifié par Bentley pour générer 623 ch à 6 000 tr/min et 760 mkg de couple à 4 000 tr/min, par le biais d'une boîte de vitesses manuelle à cinq rapports. Cette voiture était donnée pour être capable d'atteindre 350 km/h en vitesse de pointe.",118,"fr:Bentley_Hunaudières","c:0/08/%2799_Bentley_Hunaudi%C3%A8res.png"],["Q796574",54,"supercar","BMW M1","R","La BMW M1 ou BMW E26 est une supercar du constructeur automobile allemand BMW-BMW M. Produite de 1978 à 1981, elle est un échec commercial, mais a un certain succès dans les courses automobiles.","La BMW M1 ou BMW E26 est une supercar du constructeur automobile allemand BMW-BMW M.","fr:BMW_M1","c:3/39/BMW-M1-BMW-Museum.jpg"],["Q100981995",55,"supercar","Bugatti Bolide","PC","La Bugatti Bolide est une hypercar exclusivement destinée à la piste et non homologuée pour la route du constructeur automobile français Bugatti, concurrente des Lamborghini Essenza SCV12 ou Ferrari FXX K. La livraison des véhicules a débuté depuis 2024, pour un prix unitaire de quatre millions d'euros.",116,"fr:Bugatti_Bolide","c:d/d0/Bugatti_Bolide_Milano.jpg"],["Q66587547",56,"supercar","Bugatti Centodieci","C","La Bugatti Centodieci est une hypercar du constructeur automobile français Bugatti produite en 2022.",null,"fr:Bugatti_Centodieci","c:5/56/2022_Bugatti_Centodieci_in_Grigio_Chiaro%2C_front_left.jpg"],["Q56248862",57,"supercar","Bugatti Divo","PC","La Bugatti Divo est une hypercar commercialisée par le constructeur automobile français Bugatti. Produite de 2019 à 2021, son nom rend hommage à l'un des pilotes emblématiques de la marque, Albert Divo, vice champion d'Europe de course automobile.","La Bugatti Divo est une hypercar commercialisée par le constructeur automobile français Bugatti.","fr:Bugatti_Divo","c:1/16/Bugatti_Divo%2C_GIMS_2019%2C_Le_Grand-Saconnex_%28GIMS0029%29.jpg"],["Q731408",58,"supercar","Bugatti EB110","PC","La Bugatti EB110 est une voiture de sport produite par le constructeur automobile Bugatti après que la marque ait été ressuscitée à la fin des années 1980 par l'entrepreneur italien Romano Artioli. Elle est présentée au public le15 septembre 1991 sous l'arche de la Défense, près de Paris. Son nom est un hommage au fondateur de la marque, Ettore Bugatti, dont l'EB110 marque le 110e anniversaire de la naissance.",117,"fr:Bugatti_EB110","c:4/47/2007-06-15_18_Bugatti_EB_110_%28bearb_-_kl%29.jpg"],["Q61986597",59,"supercar","Bugatti La Voiture Noire","C","La Bugatti La Voiture Noire est une hypercar de luxe du constructeur automobile français Bugatti. Présentée au salon international de l'automobile de Genève 2019 ce modèle unique est basé sur la Chiron, qui rend hommage à la Bugatti Type 57 SC Atlantic produite à 4 exemplaires dont une, la 57 Atlantic noire, véhicule personnel de Jean Bugatti, a disparu entre Molsheim et Bordeaux et n'a jamais été retrouvée.","La Bugatti La Voiture Noire est une hypercar de luxe du constructeur automobile français Bugatti.","fr:Bugatti_La_Voiture_Noire","c:0/00/Bugatti_La_Voiture_Noire%2C_GIMS_2019%2C_Le_Grand-Saconnex_%28GIMS0951%29.jpg"],["Q126789787",60,"supercar","Bugatti Tourbillon","E","La Bugatti Tourbillon est une hypercar hybride produite par le constructeur automobile français Bugatti, dont la production est limitée à 250 exemplaires. Succédant à la Bugatti Chiron, la Tourbillon marque l'entrée de la marque dans l'ère de l'hybridation.",112,"fr:Bugatti_Tourbillon","c:7/75/Bugatti_Tourbillon_-_01.jpg"],["Q113565134",61,"supercar","Bugatti W16 Mistral","PC","La Bugatti Mistral est une supercar du constructeur automobile français Bugatti.",null,"fr:Bugatti_W16_Mistral","c:f/f4/Bugatti_W16_Mistral_%C3%A0_Molsheim%2C_Andy_Wallace_au_volant.png"],["Q1180394",62,"supercar","De Tomaso Pantera","E","La De Tomaso Pantera est une supercar du constructeur automobile italien De Tomaso. Présentée en 1970 lors du Salon de New York, elle est produite ensuite de 1971 à 1996. La Pantera, qui succède à la Mangusta, a été conçue par Tom Tjaarda. Contrairement au modèle précédent, qui était monté sur un châssis-poutre en acier, la Pantera possède pour la première fois dans l'histoire de De Tomaso, un châssis monocoque, lui aussi en acier.","La De Tomaso Pantera est une supercar du constructeur automobile italien De Tomaso.","fr:De_Tomaso_Pantera","c:d/d7/DeTomasoPanteraBlack.jpg"],["Q30924062",63,"supercar","Devel Sixteen","PC","La Devel Sixteen est un prototype de supercar fabriqué aux Émirats arabes unis par Devel Motors en coopération avec des ingénieurs américains et italiens.",119,"fr:Devel_Sixteen","c:4/46/Devel-sixteen.jpg"],["Q176152",64,"supercar","Ferrari 288 GTO","R","La Ferrari GTO, plus connue sous le nom non officiel de Ferrari 288 GTO, est une supercar du constructeur italien Ferrari destinée à l'époque, une fois préparée, à courir dans le FIA Groupe B; elle fut produite entre 1984 et 1985 à seulement 272 exemplaires et sa version Evoluzione pour le Groupe B servit de base de développement à la F40.",113,"fr:Ferrari_288_GTO","c:8/81/Ferrari_288_GTO_%281%29.JPG"],["Q109655897",65,"supercar","Ferrari Daytona SP3","PC","La Ferrari Daytona SP3 est une supercar du constructeur automobile italien Ferrari produite à 599+1 exemplaires à partir de fin 2021 au 2024. Elle rend hommage au triplé Ferrari lors des 24 Heures de Daytona 1967.",113,"fr:Ferrari_Daytona_SP3","c:f/fa/Ferrari_Daytona_SP3.png"],["Q121072170",66,"supercar","Ferrari F8 Tributo","R","La F8 Tributo est une voiture de sport du constructeur italien Ferrari commercialisée à partir de 2019.",null,"fr:Ferrari_F8","c:a/a0/Ferrari_F8_Tributo_Genf_2019_1Y7A5667.jpg"],["Q130549590",67,"supercar","Ferrari F80","E","La Ferrari F80 est une hypercar du constructeur automobile italien Ferrari produite à partir de 2025 en 799 exemplaires. Elle succède à la Ferrari LaFerrari, et elle est aujourd’hui la voiture la plus puissante créée par la marque, avec une puissance cumulée de 1 200 ch.","La Ferrari F80 est une hypercar du constructeur automobile italien Ferrari produite à partir de 2025 en 799 exemplaires.","fr:Ferrari_F80","c:0/00/Ferrari_F80.jpg"],["Q830381",68,"supercar","Ferrari FXX","C","La FXX est une supercar non homologuée pour la route du constructeur automobile italien Ferrari, basée sur la Ferrari Enzo et produite en 30 exemplaires de 2005 à 2007. Elle inaugure le moteur V12 de 6 262 cm3 qu'on retrouve dans tous les modèles V12 de la gamme actuelle.",117,"fr:Ferrari_FXX","c:6/6e/FoS20162016_0625_150929AA_%2827289942753%29.jpg"],["Q64162421",69,"supercar","Ferrari SF90 Stradale","R","La Ferrari SF90 Stradale est une supercar de grand tourisme hybride rechargeable du constructeur automobile italien Ferrari. Présentée en 2019 chez Ferrari à Maranello, son nom fait référence aux 90 ans de la Scuderia Ferrari fondée en 1929, et à la Formule 1 Ferrari SF90 de 2019.",115,"fr:Ferrari_SF90_Stradale","c:1/13/Red_2019_Ferrari_SF90_Stradale_%2848264238897%29_%28cropped%29.jpg"],["Q750788",70,"supercar","Ford GT","E","La Ford GT est une supercar du constructeur automobile américain Ford.",null,"fr:Ford_GT","c:b/b7/Ford_GT_Red.jpg"],["Q110732836",71,"supercar","Gordon Murray Automotive T.33","C","La Gordon Murray Automotive T.33 est une supercar du constructeur automobile britannique Gordon Murray Automotive, présentée en janvier 2022 et produite en série limitée à 100 exemplaires à partir de 2024. Elle est le second modèle du constructeur après la supercar T.50.",114,"fr:Gordon_Murray_Automotive_T.33","c:b/b4/GMA_T.33_Spider_at_Quail_2023.jpg"],["Q65129453",72,"supercar","Gordon Murray Automotive T.50","R","La T.50 est une voiture de sport du constructeur automobile britannique Gordon Murray Automotive, présentée en juin 2019 et produite en série limitée à 125 exemplaires à partir de 2022.",115,"fr:Gordon_Murray_Automotive_T.50","c:c/c8/Goodwood_Festival_of_Speed_2022_%2852172811781%29.jpg"],["Q3076234",73,"supercar","GTA Spano","C","La GTA Spano est une supercar du constructeur automobile espagnol GTA Motor, installé à Riba-roja de Túria. Elle est équipée du V10 de la Dodge Viper.","La GTA Spano est une supercar du constructeur automobile espagnol GTA Motor, installé à Riba-roja de Túria.","fr:GTA_Spano","c:9/9b/GTA_Spano_2011_schr%C3%A4g.JPG"],["Q30588296",74,"supercar","Hennessey Venom F5","PC","La Venom F5 est une Hypercar du préparateur automobile et constructeur automobile américain Hennessey, produite à 24 exemplaires à partir de 2021. Elle célèbre les 30 ans du constructeur fondé en 1991.",116,"fr:Hennessey_Venom_F5","c:a/a1/2022_Hennessey_Venom_F5_Roadster_6.6_Front.jpg"],["Q64019734",75,"supercar","Hispano-Suiza Carmen","C","L'Hispano-Suiza Carmen est une voiture de sport supercar électrique GT, du constructeur automobile espagnol Hispano-Suiza. Présentée au salon international de l'automobile de Genève 2019, elle est fabriquée à 19 exemplaires au prix de plus de 1,5 million d'euros l'unité.",107,"fr:Hispano-Suiza_Carmen","c:a/a6/Hispano-Suiza_Carmen_Genf_2019_1Y7A5641.jpg"],["Q89098423",76,"supercar","Hongqi S9","C","La Hongqi S9 est un concept car de supercar hybride du constructeur automobile chinois Hongqi présenté au salon de Francfort 2019.",114,"fr:Hongqi_S9","c:e/e4/Hongqi_S9_IAA_2019_JM_1013.jpg"],["Q521044",77,"supercar","Jaguar XJ220","R","La Jaguar XJ220 est une supercar du constructeur automobile britannique Jaguar, produite de 1992 à 1994.",null,"fr:Jaguar_XJ220","c:4/48/JaguarXJ220.jpg"],["Q943148",78,"supercar","Koenigsegg Agera","PC","L'Agera est une supercar produite par le constructeur automobile suédois Koenigsegg.",null,"fr:Koenigsegg_Agera","c:c/c3/Agera_%287501679524%29.jpg"],["Q2428693",79,"supercar","Koenigsegg Agera R","C","L'Agera R est une hypercar du constructeur automobile suédois Koenigsegg. Version évoluée de la Koenigsegg Agera, son châssis monocoque extra-léger est constitué de fibre de carbone, d'aluminium en nid d'abeilles et de Kevlar; le toit est amovible.","L'Agera R est une hypercar du constructeur automobile suédois Koenigsegg.","fr:Koenigsegg_Agera_R","c:5/52/Koenigsegg_Agera_R.jpg"],["Q2470883",80,"supercar","Koenigsegg CC","C","La Koenigsegg CC est un prototype automobile, première voiture conçue par le constructeur suédois Koenigsegg. Le projet démarre en 1995 et le prototype fait sa première apparition sur La Croisette pendant le Festival de Cannes 1997.","La Koenigsegg CC est un prototype automobile, première voiture conçue par le constructeur suédois Koenigsegg.","fr:Koenigsegg_CC","c:0/0b/1996-koenigsegg-cc-prototype_100529345_l.jpg"],["Q1993487",81,"supercar","Koenigsegg CC8S","C","La Koenigsegg CC8S est la première voiture commercialisée par le constructeur suédois Koenigsegg. Elle est inspirée du prototype Koenigsegg CC qui fait sa première apparition en 1997.","La Koenigsegg CC8S est la première voiture commercialisée par le constructeur suédois Koenigsegg.","fr:Koenigsegg_CC8S","c:8/84/Koenigsegg_side.jpg"],["Q3107340",82,"supercar","Koenigsegg CCGT","C","La Koenigsegg CCGT est une voiture de course produite par Koenigsegg en Suède. Présentée au salon international de l'automobile de Genève en 2007, elle est issue de la Koenigsegg CCR en incorporant des parties de la nouvelle CCX, modèles homologués pour la route. Un seul exemplaire a été construit.","La Koenigsegg CCGT est une voiture de course produite par Koenigsegg en Suède.","fr:Koenigsegg_CCGT","c:4/41/White_Koenigsegg_CCGT_Goodwood_2007.jpg"],["Q1147816",83,"supercar","Koenigsegg CCR","C","La Koenigsegg CCR est une supercar produite par Koenigsegg en Suède. Présentée au salon international de l'automobile de Genève en 2004, elle est très proche du modèle précédent, la Koenigsegg CC8S. La CCR est un roadster doté d'un moteur en position centrale-arrière.","La Koenigsegg CCR est une supercar produite par Koenigsegg en Suède.","fr:Koenigsegg_CCR","c:0/09/Koenigsegg-CCR-%2704.jpg"],["Q635891",84,"supercar","Koenigsegg CCX","PC","La Koenigsegg CCX est une supercar produite par Koenigsegg, en Suède, sous forme de roadster ou de coupé. Elle est dotée d'un moteur en position centrale arrière. Le modèle a été remanié pour pouvoir satisfaire aux exigences américaines.","La Koenigsegg CCX est une supercar produite par Koenigsegg, en Suède, sous forme de roadster ou de coupé.","fr:Koenigsegg_CCX","c:f/f6/Koenigsegg_CCX_roadster_%282010-10-16%29_01.jpg"],["Q2200293",85,"supercar","Koenigsegg CCXR","C","La CCXR est une hypercar produite par le constructeur automobile suédois Koenigsegg. Il s'agit d'une version dérivée de la Koenigsegg CCX fonctionnant au E85.","La CCXR est une hypercar produite par le constructeur automobile suédois Koenigsegg.","fr:Koenigsegg_CCXR","c:6/6a/Koenigsegg_CCXR_%40_Paris_-_Flickr_-_Autospotting_Crew.jpg"],["Q87031022",86,"supercar","Koenigsegg Gemera","PC","La Koenigsegg Gemera est une voiture de sport hybride produite à 300 exemplaires par le constructeur automobile suédois Koenigsegg dévoilée en mars 2020.",119,"fr:Koenigsegg_Gemera","c:9/9f/Koenigsegg_Gemera.jpg"],["Q15894547",87,"supercar","Koenigsegg One:1","C","La Koenigsegg One:1 est une voiture de type supercar, version modifiée de la Koenigsegg Agera R présentée au salon international de l'automobile de Genève 2014 et produite par le constructeur suédois Koenigsegg; les sept exemplaires produits ont tous été vendus.",114,"fr:Koenigsegg_One:1","c:b/b3/Koenigsegg_One1.jpg"],["Q19426706",88,"supercar","Koenigsegg Regera","PC","La Koenigsegg Regera est une supercar, produite par le constructeur automobile suédois Koenigsegg, dévoilée au salon international de l'automobile de Genève 2015. Sa production est limitée à 80 exemplaires, dont 40 ont trouvé leurs propriétaires en 2016-2017. La Regera est plus luxueuse et plus « pratique » que les autres sportives de la marque.",116,"fr:Koenigsegg_Regera","c:d/d0/2015-03-03_Geneva_Motor_Show_3314.JPG"],["Q22981838",89,"supercar","Lamborghini Centenario","C","La Lamborghini Centenario LP770-4 est une supercar du constructeur automobile italien Lamborghini et présentée le 1er mars 2016 au salon international de l'automobile de Genève.",117,"fr:Lamborghini_Centenario","c:5/5f/2016-03-01_Geneva_Motor_Show_0789_%28cropped%29.JPG"],["Q135855033",90,"supercar","Lamborghini Fenomeno","PC","La Lamborghini Fenomeno est une supercar produite par le constructeur automobile italien Lamborghini en 44 exemplaires à partir de 2025",118,"fr:Lamborghini_Fenomeno","c:d/d4/2025_Lamborghini_Fenomeno_USG26.jpg"],["Q842432",91,"supercar","Lamborghini Reventón","PC","La Lamborghini Reventón est une supercar du constructeur automobile italien Lamborghini présentée lors du salon de l'automobile de Francfort 2007. Initialement conçue exclusivement en modèle coupé, elle sera déclinée en version roadster en 2009, bénéficiant des évolutions mécaniques de la Murciélago SV.",114,"fr:Lamborghini_Reventón","c:1/1b/Lamborghini_Revent%C3%B3n.jpg"],["Q117309045",92,"supercar","Lamborghini Revuelto","E","La Lamborghini Revuelto est une supercar de type hybride rechargeable, développée par le constructeur automobile italien Lamborghini et dévoilée en mars 2023. Elle succède à la Lamborghini Aventador.",112,"fr:Lamborghini_Revuelto","c:2/21/2023_Lamborghini_Revuelto.jpg"],["Q1341985",93,"supercar","Lexus LFA","E","La Lexus LFA est un modèle coupé produit par Lexus, limitée à une production de 500 exemplaires. C'est le second modèle de la ligne F après l'IS F de fin 2007, mais surtout la première supercar du constructeur nippon. La « A » vient de l’anglais « apex » signifiant point de corde d’un virage.","La Lexus LFA est un modèle coupé produit par Lexus, limitée à une production de 500 exemplaires.","fr:Lexus_LFA","c:c/c9/Lexus_LFA_005.JPG"],["Q65054542",94,"supercar","Lotus Evija","PC","La Lotus Evija est une hypercar électrique du constructeur automobile britannique Lotus. Produite à 130 exemplaires à partir de 2020 mais reporté à 2023 pour les premières livraisons. C'est le premier véhicule électrique de la marque.","La Lotus Evija est une hypercar électrique du constructeur automobile britannique Lotus.","fr:Lotus_Evija","c:1/12/Lotus_Evija_front.jpg"],["Q13408086",95,"supercar","Lykan HyperSport","PC","La Lykan HyperSport est la première supercar produite par la compagnie W Motors, une entreprise née au Liban et désormais basée aux Émirats arabes unis. C'est aussi la première supercar produite par une entreprise du Moyen-Orient.",111,"fr:Lykan_HyperSport","c:e/e6/Lykan_HyperSport.jpg"],["Q389575",96,"supercar","Maserati MC12","PC","La MC12 est une supercar biplace du constructeur automobile italien Maserati conçue pour participer au championnat FIA GT. La MC12 est entrée en production en 2004, avec seulement 25 voitures dont cinq destinées à la vente. En 2005, 25 voitures de plus ont été produites, soit un total de cinquante MC12 disponibles pour les clients à un prix unitaire de 600 000 € à l'époque. Maserati a aussi produit douze Maserati MC12 Corsa.",118,"fr:Maserati_MC12","c:a/a2/Maserati_MC12_2-cropped.jpg"],["Q28913682",97,"supercar","McLaren 720S","R","La 720S est une supercar du constructeur automobile britannique McLaren Automotive, produite de 2017 à 2022. Elle appartient à la gamme des « Super Series » du constructeur. Elle succède à la 650S et elle est remplacée par la 765LT en 2020 puis par la 750S en 2023.","La 720S est une supercar du constructeur automobile britannique McLaren Automotive, produite de 2017 à 2022.","fr:McLaren_720S","c:4/43/McLaren_720S_IMG_0933.jpg"],["Q75234729",98,"supercar","McLaren Elva","C","Supercar",null,"fr:McLaren_Elva","c:7/7f/2020_McLaren_Elva_4.0_Front.jpg"],["Q3353470",99,"supercar","McLaren F1 LM","C","La McLaren F1 LM est une version extrême de la McLaren F1, supercar britannique légendaire qui a remporté les 24 Heures du Mans 1995. Seuls cinq exemplaires de la LM ont été construits en hommage à cette victoire.","","en:McLaren_F1_LM","c:1/16/1996_McLaren_F1_Chassis_No_63_6.1_Front.jpg"],["Q6407533",100,"supercar","McLaren P1","R","La McLaren P1 est la première voiture de sport hybride du constructeur automobile britannique McLaren Automotive, mais aussi dans le monde. Elle est présentée au salon international de l'automobile de Genève 2013 et est fabriquée en 375 exemplaires.",118,"fr:McLaren_P1","c:c/c8/McLaren_P1.jpg"],["Q45304944",101,"supercar","McLaren Senna","PC","La Senna est une hypercar du constructeur automobile britannique Mclaren présentée le 10 décembre 2017.",null,"fr:McLaren_Senna","c:9/91/McLaren_Senna_9.jpg"],["Q113579330",102,"supercar","McLaren Solus GT","C","La McLaren Solus GT est une supercar monoplace réservée au circuit, produite en série très limitée par McLaren. Son look de voiture de course futuriste vient du jeu vidéo Gran Turismo.","","en:McLaren_Solus_GT","c:6/64/2023_McLaren_Solus_GT.jpg"],["Q57831546",103,"supercar","McLaren Speedtail","C","La Speedtail est une hypercar de la gamme « Ultimate Series » du constructeur automobile britannique Mclaren, dévoilée le 26 octobre 2018.",118,"fr:McLaren_Speedtail","c:f/fb/2019_McLaren_Speedtail_%28Rob_Melville%29_%28cropped%29.jpg"],["Q28669404",104,"supercar","Mercedes-AMG One","R","La Mercedes-AMG One est une hypercar du constructeur automobile allemand Mercedes-AMG, présentée au salon de l'automobile de Francfort 2017 à l'occasion du cinquantenaire de son département sportif AMG, sous la forme d'un concept car. Son moteur est dérivé de celui utilisé par la Mercedes F1 W07 en Championnat du monde de Formule 1 par l'écurie Mercedes-AMG avec laquelle remporte le Championnat pilote et constructeur.",108,"fr:Mercedes-AMG_One","c:3/3b/Mercedes-AMG_One_IAA_2021_1X7A0108.jpg"],["Q207624",105,"supercar","Mercedes-Benz SLR McLaren","R","La Mercedes SLR Mclaren est une supercar que le constructeur automobile Mercedes-Benz et McLaren Automotive ont développé conjointement de 2003 à 2010, lorsque Mercedes-Benz possédait 40 % de McLaren. Sa désignation est un hommage à une voiture de course légendaire: le 300 SLR de 1955. Simultanément, le SLR pour « Sport, Leicht, Rennsport » rappelle les bolides Mercedes-Benz qui remportèrent tant de victoires dans les années 1930, ce qui leur valut leur célèbre surnom « Flèches d'Argent ».",111,"fr:Mercedes-Benz_SLR_McLaren","c:e/ea/MercedesBenz_SLR_McLaren.jpg"],["Q1414821",106,"supercar","Pagani Huayra","R","La Pagani Huayra est une automobile du constructeur italien Pagani qui fut présentée lors du Salon international de l'automobile de Genève 2011.",115,"fr:Pagani_Huayra","c:a/ac/PaganiHuayra.jpg"],["Q113960878",107,"supercar","Pagani Utopia","PC","La Pagani Utopia est une Hypercar du constructeur automobile italien Pagani disponible à partir du 2022 en version coupé, produite en 99 exemplaires — et en version roadster à partir de 2024.",114,"fr:Pagani_Utopia","c:f/fc/Pagani_Utopia_3.jpg"],["Q1756139",108,"supercar","Porsche 911 GT3","E","La Porsche 911 GT3 est une automobile de sport du constructeur allemand Porsche mise sur le marché en 1999. C'est une version haute performance de la 911. Elle est assemblée à Stuttgart, en Allemagne. Elle connaît plusieurs évolutions majeures, avec la 911 type 996, 997, 991 et 992.","La Porsche 911 GT3 est une automobile de sport du constructeur allemand Porsche mise sur le marché en 1999.","fr:Porsche_911_GT3","c:4/48/2005_Porsche_911_GT3_-_Flickr_-_The_Car_Spy_%2812%29.jpg"],["Q575937",109,"supercar","Porsche 959","R","La Porsche 959 est une voiture sportive produite par Porsche. Elle apparaît en 1983 au salon de Francfort sous la forme d'un prototype, la 911 Groupe B. Peu avant, la Fédération internationale de l'automobile avait changé ses règlements pour encourager les constructeurs à faire de la compétition: il ne fallait plus commercialiser que deux cents exemplaires pour pouvoir prendre part aux compétitions du Groupe B.","La Porsche 959 est une voiture sportive produite par Porsche.","fr:Porsche_959","c:5/55/Porsche_959_silver_at_Auto_Salon_Singen.jpg"],["Q893186",110,"supercar","Rimac Concept One","PC","La Rimac Concept One est une voiture de sport électrique conçue par le constructeur croate Rimac Automobili basée à Sveta Nedelja. Sa production est limitée à huit exemplaires.",115,"fr:Rimac_Concept_One","c:1/17/Rimac_Concept_One_-_Salon_Priv%C3%A9_London_2012_%287956529248%29.jpg"],["Q50379367",111,"supercar","Rimac Nevera","R","La Rimac Nevera, connue en interne sous le nom de C_Two pour la version de développement, est une voiture de sport électrique produite à partir de 2021 par le constructeur automobile croate Rimac Automobili, basé à Sveta Nedelja.",114,"fr:Rimac_Nevera","c:2/22/Rimac_Nevera.jpg"],["Q1369208",112,"supercar","Saleen S7","PC","La Saleen S7 est une supercar construite par l'entreprise américaine Saleen. Elle a été dévoilée pour la première fois le 19 août 2000, au circuit de Laguna Seca.","La Saleen S7 est une supercar construite par l'entreprise américaine Saleen.","fr:Saleen_S7","c:a/ab/SAG2004_181_Saleen.jpg"],["Q2478144",113,"supercar","Spyker C12 Zagato","C","La Spyker C12 Zagato est une supercar néerlandaise en aluminium, produite en édition limitée et dessinée avec le carrossier italien Zagato.","","en:Spyker_C12_Zagato","c:9/9c/STA42533.JPG"],["Q535957",114,"supercar","SSC Tuatara","PC","La Tuatara est une supercar conçue par le constructeur américain SSC North America à partir de 2021, pour succéder à la SSC Ultimate Aero. Elle devait sortir en 2012, mais le projet fut abandonné par la marque, puis relancé en 2018 par Jerod Shelby.",119,"fr:SSC_Tuatara","c:3/3d/2019_SSC_Tuatara_at_Pebble_Beach_Press_Conference.jpg"],["Q848954",115,"supercar","SSC Ultimate Aero","C","La SSC Ultimate Aero XT est une supercar construite par Shelby Super Cars dans le but de rivaliser avec la Bugatti Veyron 16.4. Elle a une vitesse de pointe de 412 km/h, et un temps de 2,78 secondes pour le 0 à 100 km/h.",114,"fr:SSC_Ultimate_Aero","c:8/80/SSC_Ultimate_Aero_TT_-_1.jpg"],["Q43253563",116,"supercar","Tesla Roadster","M","La Tesla Roadster II est un concept car de voiture de sport GT 2+2 électrique du constructeur automobile américain Tesla, présentée en 2017 au siège de SpaceX à Hawthorne en Californie.",114,"fr:Tesla_Roadster_(deuxième_génération)","c:5/5e/The_Wicked-Fast_Next_Gen_Roadster.jpg"],["Q2003911",117,"supercar","Ultima GTR","C","L'Ultima GTR est une automobile supersportive ou supercar fabriquée par Ultima Sports Ltd basée à Hinckley dans le Leicestershire en Angleterre. Elle est disponible à la vente à la fois en kit et en voiture prête à rouler. Elle est également disponible en version cabriolet sous le nom de Ultima Can-Am.",114,"fr:Ultima_GTR","c:c/cd/Ultima_GTR_2005.jpg"],["Q1062745",118,"supercar","Venturi Fétish","C","La Venturi Fétish est la première voiture de sport 2 places électrique au monde. Elle est produite par le constructeur français Venturi à Monaco.","La Venturi Fétish est la première voiture de sport 2 places électrique au monde.","fr:Venturi_Fétish","c:3/33/Stand_Venturi_Mondial_2006.jpg"],["Q622071",119,"moto","Aprilia 125 RS","C","L'Aprilia RS 125 est une moto homologuée pour l'utilisation routière inspirée par la moto de course RSW 125 sur laquelle de nombreux pilotes dont Valentino Rossi ont été champions du monde.",111,"fr:Aprilia_125_RS","c:d/d3/Aprilia_RS125.jpg"],["Q20072402",120,"moto","Aprilia RS-GP","C","L'Aprilia RS-GP est un modèle de moto de course du constructeur italien Aprilia.",null,"fr:Aprilia_RS-GP","c:0/06/Aleix_Espargar%C3%B3_leads_the_pack_2021_Sachsenring_%28cropped%29.jpg"],["Q1747291",121,"moto","Aprilia RSV4","C","L'Aprilia RSV4 est la moto sportive vedette du constructeur italien Aprilia, équipée d'un moteur V4. Elle a remporté plusieurs titres en championnat du monde Superbike.","","en:Aprilia_RSV4","c:b/bb/Moscow%2C_Aprilia_RSV4%2C_June_2025_01.jpg"],["Q796435",122,"moto","BMW C1","C","Le BMW C1 est un modèle de scooter produit par le constructeur allemand BMW.",null,"fr:BMW_C1","c:e/e2/BMW_C1_FF_200_%28frontale%29.jpg"],["Q632194",123,"moto","BMW R 1150 GS","C","La R 1150 GS est un modèle de motocyclette du constructeur bavarois BMW.",null,"fr:BMW_R_1150_GS","c:9/9a/BMW_R1150GS.JPG"],["Q796683",124,"moto","BMW R 1200 GS","C","La BMW R 1200 GS est un modèle de moto du constructeur bavarois BMW Motorrad.",null,"fr:BMW_R_1200_GS","c:8/8d/1200gsfr.jpg"],["Q796691",125,"moto","BMW R 1200 RT","C","La BMW R 1200 RT est un modèle de motocyclette du constructeur bavarois BMW.",null,"fr:BMW_R_1200_RT","c:4/41/Left-front-w2.jpg"],["Q1971266",126,"moto","BMW R 32","C","La BMW R 32 est le premier modèle de moto du constructeur allemand BMW. Produite à 3090 exemplaires de 1923 à 1926, elle inaugure l'architecture avec moteur boxer et transmission finale par arbre que BMW utilisera ensuite sans interruption jusqu'à nos jours.","La BMW R 32 est le premier modèle de moto du constructeur allemand BMW.","fr:BMW_R_32","c:c/cb/Mus%C3%A9e_BMW_015_-_BMW_R_32.jpg"],["Q683661",127,"moto","BMW R 75","C","Pour la moto 750 cm3 des années 1970 voir BMW R 75/5",null,"fr:BMW_R_75","c:c/c8/BMW_R75_back.jpg"],["Q796756",128,"moto","BMW S 1000 RR","R","La S 1000 RR est un modèle de moto sportive de la firme bavaroise BMW.",null,"fr:BMW_S_1000_RR","c:c/c3/S1000RR_Composing.jpg"],["Q3645403",129,"moto","Brough Superior SS100","C","La Brough Superior SS100 est une moto anglaise de luxe créée en 1924, surnommée la « Rolls-Royce des motos ». Lawrence d'Arabie en possédait plusieurs et est mort au guidon de l'une d'elles.","","en:Brough_Superior_SS100","c:d/d1/Brough_Superior_SS_1000_1925.jpg"],["Q474502",130,"moto","Daimler Reitwagen","C","Daimler Reitwagen est un prototype de moto à moteur à gaz de 1885, des inventeurs allemands Gottlieb Daimler et Wilhelm Maybach. Elle est reconnue comme le premier prototype de moto à moteur à explosion de l'histoire de l'automobile.",119,"fr:Daimler_Reitwagen","c:2/22/Mercedes-Benz-Museum_2015-01_by-RaBoe_027.jpg"],["Q907619",131,"moto","Dodge Tomahawk","PC","La Dodge Tomahawk est un véhicule terrestre monoplace, hybride mi-auto mi-moto.",null,"fr:Dodge_Tomahawk","c:1/1d/Hemi_powered_motorcycle_--_Walter_P_Chrysler_Museum_10-23-2010_148_N.jpg"],["Q648431",132,"moto","Ducati 1098/1198","C","La 1098 est un modèle de motocyclette de la marque italienne Ducati.",null,"fr:Ducati_1098/1198","c:8/86/Ducati_1098_2.jpg"],["Q2229184",133,"moto","Ducati 748","C","La 748 est une moto de chez Ducati de type sportive. Sa production débuta en 1995 pour se terminer en 2003.","La 748 est une moto de chez Ducati de type sportive.","fr:Ducati_748","c:5/50/Ducati_748_Studio.jpg"],["Q1263348",134,"moto","Ducati 848","C","La 848 est un modèle de moto sportive du constructeur italien Ducati.",null,"fr:Ducati_848","c:1/16/Ducati_848.jpg"],["Q1263357",135,"moto","Ducati 916","C","La 916 est une moto sportive construite par Ducati de la famille Desmoquattro.",null,"fr:Ducati_916","c:9/9f/Ducati_916.JPG"],["Q1263363",136,"moto","Ducati 999","C","La 999 est une moto sportive construite par Ducati. Elle est apparue pour la première fois en 2003. Elle a la lourde tâche de remplacer ses illustres aînées 916, 996 et 998. La 999 présente une esthétique tranchée, les lignes sont taillées à la serpe. Elle est dessinée par Pierre Terblanche. Le moteur est un classique bicylindre en V à 90° type Testastretta. L'alimentation se fait par un système d'injection électronique Magneti Marelli. Le cadre est un habituel treillis tubulaire en acier.","La 999 est une moto sportive construite par Ducati.","fr:Ducati_999","c:8/87/Ducati_999_2005.jpg"],["Q1263380",137,"moto","Ducati Desmosedici GP","C","La Desmosedici est un modèle de moto de compétition du constructeur italien Ducati.",null,"fr:Ducati_Desmosedici_GP","c:7/74/Loris_Capirossi_MotoGP_China_2007.jpg"],["Q2638436",138,"moto","Ducati Diavel","C","La Diavel est un modèle de moto du constructeur italien Ducati.",null,"fr:Ducati_Diavel","c:6/65/Ducati_Diavel_2_modified.jpg"],["Q1263388",139,"moto","Ducati Monster","PC","Ducati Monster est une gamme de motos du constructeur italien Ducati de type roadster lancée en 1992. En France, elle est souvent appelée Mostro, car lors de la présentation de ce modèle, le magazine Moto Revue avait titré « Il Mostro ». Le nom officiel a toujours été « Monster », le premier modèle présentait l'inscription « Monster » sur le réservoir, en dessous du logo Ducati.","Ducati Monster est une gamme de motos du constructeur italien Ducati de type roadster lancée en 1992.","fr:Ducati_Monster","c:1/19/S2R1000-101_v2_1024_web.jpg"],["Q1263395",140,"moto","Ducati Multistrada","C","La Multistrada est un modèle de moto de la firme italienne Ducati. Elle est disponible en quatre cylindrées.","La Multistrada est un modèle de moto de la firme italienne Ducati.","fr:Ducati_Multistrada","c:1/14/Ducati_Multistrada_1000s_DS.jpg"],["Q48816161",141,"moto","Ducati Panigale V4","PC","La Ducati Panigale V4 est une moto sportive italienne lancée en 2018, avec un moteur V4 de plus de 1 100 cm³ dérivé de la MotoGP.","","en:Ducati_Panigale_V4","c:a/a8/Ducati_Panigale_V4_-_Tuning_World_Bodensee_2018%2C_Friedrichshafen_%28OW1A0484%29.jpg"],["Q28126796",142,"moto","Harley-Davidson Fat Boy","C","La Fat Boy est un modèle de moto de la marque Harley-Davidson. Elle est classée dans la famille Softail, puis Cruiser après la disparition des Dyna. Elle est équipée d'un moteur bicylindre en V avec des jantes de roues pleines. Conçu à l'origine par Willie G. Davidson et Louie Netz, Harley-Davidson a construit un prototype de Fat Boy pour le rassemblement de la Bike Week de Daytona Beach, en 1988 et 1989. La Fat Boy est rentrée en production à partir de 1990. Ses codes usines sont FLSTF, et FLFB à partir de 2018.","La Fat Boy est un modèle de moto de la marque Harley-Davidson.","fr:Harley-Davidson_Fat_Boy","c:9/99/Harley_Davidson_Fat_Boy_2018_FLFBS.jpg"],["Q1207631",143,"moto","Harley-Davidson Sportster","PC","La Harley-Davidson Sportster est une gamme de motos fabriquées de manière continue depuis 1957 par Harley-Davidson. Les modèles Sportster sont désignés par un code produit de Harley-Davidson commençant par « XL ». En 1952, sont commercialisés les prédécesseurs du Sportster, les modèles K Sport et Sport Solo. Ces modèles K, KK, KH et KHK de 1952 à 1956 avaient un moteur à soupapes latérales, alors que les modèles plus récents du XL Sportster utilisent un moteur à soupapes en tête.","La Harley-Davidson Sportster est une gamme de motos fabriquées de manière continue depuis 1957 par Harley-Davidson.","fr:Harley-Davidson_Sportster","c:f/f1/1957_Harley-Davidson_XL_Sportster.jpg"],["Q741485",144,"moto","Honda CB 1000 R","C","La CB 1000 R est une moto produite par Honda depuis 2008. Elle a été créée pour se positionner sur le segment des gros « roadster ». D'une cylindrée de 999 cm3, elle développe 125 ch DIN pour environ 217 kg tout pleins faits. Elle n'est donc pas éligible au permis A2 en France.","La CB 1000 R est une moto produite par Honda depuis 2008.","fr:Honda_CB_1000_R","c:3/3f/Honda_CB1000R.png"],["Q1626492",145,"moto","Honda CB 1300","C","La CB 1300 Super Four est un modèle de motocyclette commercialisé par Honda.",null,"fr:Honda_CB_1300","c:0/02/HONDA_CB1300_RB.JPG"],["Q1626541",146,"moto","Honda CB 750 Four","PC","La CB 750 Four est un modèle de moto produit par le groupe japonais Honda de 1968 à 1977, et qui marque, pour la plupart des observateurs, le passage à l'ère de la moto moderne.",112,"fr:Honda_CB_750_Four","c:9/9a/Honda_CB_750_k1.jpg"],["Q387353",147,"moto","Honda CBF 125","C","La CBF 125 est un modèle de motocyclette, de type Sport GT, du constructeur japonais Honda. Elle est assemblée en Inde par HMSI à partir de 2008. Sur le marché Indien, elle est connue sous le nom Stunner pour la version carburateur et sous le nom Stunner PGM-FI pour la version injection. Sur le marché européen, seule la version injection est disponible.","La CBF 125 est un modèle de motocyclette, de type Sport GT, du constructeur japonais Honda.","fr:Honda_CBF_125","c:f/fa/CBF125_01.JPG"],["Q1281878",148,"moto","Honda CBR 1100 XX","C","La Honda CBR 1100 XX est une moto japonaise fabriquée par Honda, catégorie sport grand tourisme. Appelée aussi « Superblackbird », elle a été présentée en septembre 1996 en Europe. Elle a détrôné la Kawasaki ZZR 1100 en tant que moto la plus rapide du monde avec 297,3 km/h pour la ZZR 1100 et 312 km/h pour la CBR XX 1100.","La Honda CBR 1100 XX est une moto japonaise fabriquée par Honda, catégorie sport grand tourisme.","fr:Honda_CBR_1100_XX","c:c/c9/Honda_CBR_1100_XX_silver_vr.jpg"],["Q1626498",149,"moto","Honda CBR1000F","C","La Honda CBR1000F Hurricane est une moto sportive de grand tourisme produite par Honda de 1987 à la fin des années 1990, avec un quatre-cylindres de 998 cm³.","","en:Honda_CBR1000F","c:c/c4/1994_Honda_CBR1000F_Hurricane%2C_front_left.jpg"],["Q2733256",150,"moto","Honda CBR1000RR","PC","La Honda CBR1000RR Fireblade est une moto sportive produite par Honda depuis 2004, héritière de la célèbre lignée CBR900RR lancée en 1992.","","en:Honda_CBR1000RR","c:2/24/2024_Honda_CBR1000RR-R_Fireblade_SP.jpg"],["Q1626503",151,"moto","Honda CBR125R","C","La Honda CBR125R est une petite moto sportive de 125 cm³ produite par Honda depuis 2004, très populaire auprès des jeunes motards.","","en:Honda_CBR125R","c:4/47/Honda_CBR125R.jpg"],["Q1626496",152,"moto","Honda CBR250R","C","La Honda CBR250R est une moto sportive légère monocylindre produite par Honda depuis 2011, idéale pour débuter.","","en:Honda_CBR250R,_CBR300R,_and_CB300F","c:c/cc/Honda_CBR250R_%D1%83%D0%BA%D1%80%D0%B0%D1%97%D0%BD%D1%81%D1%8C%D0%BA%D0%BE%D0%B3%D0%BE_%D0%B2%D0%BB%D0%B0%D1%81%D0%BD%D0%B8%D0%BA%D0%B0.jpg"],["Q1626501",153,"moto","Honda CBR600RR","PC","La Honda CBR600RR est une moto sportive de 599 cm3, de la gamme des CBR, introduite par Honda en 2003. Elle remporta entre 2002 et 2008 chaque Championnat du monde de Supersport. Elle réitère la performance en 2010, puis à nouveau en 2014. Elle rencontre rapidement un grand succès et reste l'une des sportives en 600 cm3 les plus appréciées en Europe.","La Honda CBR600RR est une moto sportive de 599 cm3, de la gamme des CBR, introduite par Honda en 2003.","fr:Honda_CBR600RR","c:5/5e/Honda_CBR_600RR_2013_HRC.jpg"],["Q972048",154,"moto","Honda CG125","PC","La Honda CG125 est une moto légère produite par Honda depuis 1975.",null,"fr:Honda_CG125","c:c/cc/Honda_CG_125_de_1976.jpg"],["Q1146816",155,"moto","Honda GL","R","La Honda GL est un modèle de moto commercialisé par Honda, faisant partie de la série des Gold Wing apparue en 1975, avec la 1000 à quatre cylindres.",116,"fr:Honda_GL","c:f/fc/Honda_1000_GL.jpg"],["Q1626526",156,"moto","Honda Hornet","C","La Hornet est un modèle de moto de type roadster, du constructeur japonais Honda.",null,"fr:Honda_Hornet","c:5/53/Honda_Hornet_600_2005.jpg"],["Q1739112",157,"moto","Honda Innova","C","La série Honda Innova, Honda Wave, ou Honda Supra est une série de petites motocyclettes fabriquées par Honda. Ce modèle est issu de la « série NF » ou « NF series » en anglais. Seul le nom commercial du modèle change à l'export.","La série Honda Innova, Honda Wave, ou Honda Supra est une série de petites motocyclettes fabriquées par Honda.","fr:Honda_Innova","c:2/21/Honda_Innova_2007_gris.jpg"],["Q772791",158,"moto","Honda NSR 500","C","La Honda NSR 500 est un prototype de moto de compétition à moteur 2 temps du constructeur japonais Honda, conçu pour les épreuves de Grand Prix moto. Elle a été créée par le HRC et a commencé sa carrière en 1984 en catégorie 500 cm3. Honda a remporté dix championnats du monde 500 cm3 avec la NSR500 de 1984 à 2002 et six entre 1994 et 1999. Avec plus de 100 victoires à son actif.",116,"fr:Honda_NSR_500","c:6/6f/Honda_nsr500_honda_collection_hall.JPG"],["Q1626637",159,"moto","Honda NSR125","C","La Honda NSR125 est une moto sportive de 125 cm³ à moteur deux-temps, produite de 1988 à 2001. Son nom vient de la moto de Grand Prix NSR500.","","en:Honda_NSR125","c:c/ca/2x_Honda_NSR_125.JPG"],["Q1626655",160,"moto","Honda RC211V","C","La Honda RC211V est un modèle de moto de compétition du constructeur japonais Honda, dotée d’un moteur à quatre temps V5.",117,"fr:Honda_RC211V","c:4/4d/Daniel_Pedrosa.jpg"],["Q2535849",161,"moto","Honda RC212V","C","La RC212V est un modèle de moto de compétition du constructeur japonais Honda conçu pour le MotoGP.",null,"fr:Honda_RC212V","c:5/5b/NickyHayden2.jpg"],["Q2061492",162,"moto","Honda RC213V","C","La Honda RC213V est un modèle de moto du constructeur japonais Honda.",null,"fr:Honda_RC213V","c:3/37/Dani_pedrosa_honda_motogp_mugello_2012.jpg"],["Q1626729",163,"moto","Honda Shadow","C","La Honda Shadow est une famille de motos custom (cruisers) produite par Honda depuis 1983, avec un moteur bicylindre en V refroidi par liquide.","","en:Honda_Shadow","c:a/ad/20130210-RLR_6284_%288464991228%29.jpg"],["Q1192736",164,"moto","Honda Super Cub","PC","La Honda Super Cub est une série de motocyclettes produite par Honda avec un moteur monocylindre à quatre temps avec une cylindrée de 49 à 124 cm3.",116,"fr:Honda_Super_Cub","c:d/d0/Honda_super_cub%2C_1st_Gen._1958%2C_Left_side.jpg"],["Q609001",165,"moto","Honda Transalp","C","Le terme Transalp désigne un modèle de moto à vocation trail, produit par la marque Honda de 1987 à 2012. Elle réapparut au catalogue de juin à décembre 2013 avant de disparaître en 2014 avec l'apparition de la NC750X. Le modèle réapparaît en 2023 avec un moteur bicylindre en ligne.","Le terme Transalp désigne un modèle de moto à vocation trail, produit par la marque Honda de 1987 à 2012.","fr:Honda_Transalp","c:b/b2/2025_Honda_XL750_Transalp_%282%29.jpg"],["Q6022805",166,"moto","Indian scout","C","L'Indian Scout est une moto américaine du constructeur Indian, lancée en 1920 et relancée en 2015. Ce cruiser bicylindre est l'un des modèles les plus célèbres de la marque.","","en:Indian_scout",""],["Q1737329",167,"moto","Kawasaki 900 Z1","C","La 900 Z1 Kawasaki est le premier modèle de moto quatre temps sorti par Kawasaki après une série de motos à moteur deux temps. Elle inaugure la gamme des Z, à l'exception de la 650 W héritée de Meguro, inspirée de la BSA britannique et non importée en France.",119,"fr:Kawasaki_900_Z1","c:6/65/Kawasaki_900.jpg"],["Q1737312",168,"moto","Kawasaki KLR650","C","La Kawasaki KLR650 est une moto trail de 650 cm3 produite par l'entreprise japonaise Kawasaki depuis 1987. Sa production a été arrêtée en 2018 puis reprise en 2022 pour y intégrer un moteur à injection et un système ABS.","La Kawasaki KLR650 est une moto trail de 650 cm3 produite par l'entreprise japonaise Kawasaki depuis 1987.","fr:Kawasaki_KLR650","c:1/1a/2009_black_Kawasaki_KLR_650.jpg"],["Q1737299",169,"moto","Kawasaki Ninja 250R","C","La Kawasaki Ninja 250R est la petite moto sportive d'entrée de gamme de Kawasaki, lancée en 1986 et restée presque inchangée pendant un quart de siècle.","","en:Kawasaki_Ninja_250R","c:0/00/2009_Kawasaki_Ninja_250R_Black.jpg"],["Q18387355",170,"moto","Kawasaki Ninja H2","R","La Kawasaki Ninja H2 est une hypersportive à compresseur, l'une des motos de série les plus puissantes au monde. Sa version piste H2R dépasse les 300 chevaux.","","en:Kawasaki_Ninja_H2","c:4/4f/Kawasaki_Ninja_H2.jpg"],["Q1737315",171,"moto","Kawasaki Vulcan","C","La Kawasaki Vulcan est une gamme de motos custom produite depuis 1984, avec des moteurs bicylindres en V allant de 400 à plus de 2 000 cm³.","","en:Kawasaki_Vulcan","c:9/95/Kawasaki_Vulcan_1500_%282000%29.jpg"],["Q56298238",172,"moto","Kawasaki Z900","C","La Kawasaki Z900 est un roadster produit depuis 2017, qui a remplacé la Z800. Elle a longtemps été le modèle phare de la gamme Z.","","en:Kawasaki_Z900","c:b/bc/Kawasaki_Z900%2C_green.jpg"],["Q1737325",173,"moto","Kawasaki ZX-10R","PC","La ZX-10R est un modèle de moto sportive du constructeur japonais Kawasaki.",null,"fr:Kawasaki_ZX-10R","c:2/2f/Kawasaki_ZX-10R_2004_blue.jpg"],["Q1382502",174,"moto","Kawasaki ZX-12R","C","La Kawasaki Ninja ZX-12R est un modèle de motocyclette du constructeur japonais Kawasaki, appartenant à la gamme de motos sportives, produite de 2000 à 2006.",115,"fr:Kawasaki_ZX-12R","c:6/68/ZX12R-2001.jpg"],["Q1737326",175,"moto","Kawasaki ZX-6R","PC","La Kawasaki ZX-6R est une moto de 636 cm3, première supersportive de la marque introduite en 1995. Elle détrône la 600 ZZR qui correspond désormais à une moto de type GT. La ZX-6R est la première 600 du marché équipée d'un cadre en alliage léger.","La Kawasaki ZX-6R est une moto de 636 cm3, première supersportive de la marque introduite en 1995.","fr:Kawasaki_ZX-6R","c:b/bd/Kawasaki_Ninja_ZX-6R_636_ABS_2020.jpg"],["Q1737343",176,"moto","Kawasaki ZZR","C","La Kawasaki ZZR1400 (ou Ninja ZX-14) est une hypersportive présentée en 2005, la moto la plus puissante de Kawasaki à sa sortie.","","en:Kawasaki_Ninja_ZX-14","c:0/08/Kawasaki_ZZR_1400_-_2018_-_Mondial_de_l%27Automobile_de_Paris_2018_-_001.jpg"],["Q30592746",177,"moto","KTM 1290 Super Duke R","C","La KTM 1290 Super Duke R est un roadster autrichien surnommé « The Beast », animé par un bicylindre en V de 1 301 cm³, le plus puissant jamais construit par KTM.","","en:KTM_1290_Super_Duke_R","c:8/84/KTM_1290_Super_Duke_R.jpg"],["Q1412490",178,"moto","Lambretta","PC","Lambretta est une marque de scooters fabriqués par la société italienne Innocenti S.p.A. qui doit son nom à son usine implantée sur la commune de Lambrate près de Milan. Cette marque a été créée en 1947 et a cessé ses activités en 1972, avant de renaître et lancer de nouveaux modèles en 2018.","Lambretta est une marque de scooters fabriqués par la société italienne Innocenti S.p.A.","fr:Lambretta","c:e/e7/Lambretta_Roller.JPG"],["Q1062085",179,"moto","MV Agusta F4","C","La F4 est un modèle de moto sportive construite par la firme italienne MV Agusta, commercialisée depuis 1999.",null,"fr:MV_Agusta_F4","c:c/cf/2006_MV_Agusta_F4_CC%2C_front_right_%28Greenwich_2025%29.jpg"],["Q730833",180,"moto","Norton Commando","C","La Commando est un modèle de moto du constructeur britannique Norton.",null,"fr:Norton_Commando","c:3/3a/1973_Norton_850.JPG"],["Q1091424",181,"moto","Piaggio Ciao","C","Le Ciao est un modèle de cyclomoteur de 49,9 cm3 fabriqué par le constructeur italien Piaggio. Sa production commence en 1967 et se termine en 2006. Pendant près de quarante ans, le Ciao s'est vendu à plus de trois millions et demi d'exemplaires. Il est le cyclomoteur italien le plus vendu au monde après la Vespa. Sa vitesse maximale varie en fonction des pays où sa vente est destinée.","Le Ciao est un modèle de cyclomoteur de 49,9 cm3 fabriqué par le constructeur italien Piaggio.","fr:Piaggio_Ciao","c:9/91/Ciao_mix.JPG"],["Q7374148",182,"moto","Royal Enfield Bullet","PC","La Royal Enfield Bullet est une moto monocylindre née en Angleterre en 1932 et produite aujourd'hui en Inde. C'est l'un des modèles de moto produits le plus longtemps au monde.","","en:Royal_Enfield_Bullet","c:8/84/Royal_Enfield_Bullet_500_-_2002_model.jpg"],["Q2000575",183,"moto","Suzuki B-King","C","La B-King est un modèle de motocyclette produit par le constructeur japonais Suzuki.",null,"fr:Suzuki_B-King","c:0/08/Suzuki_BKing.jpg"],["Q1509220",184,"moto","Suzuki DL 650 V-Strom","C","La 650 V-Strom est un modèle de motocyclette produit par le constructeur japonais Suzuki.",null,"fr:Suzuki_DL_650_V-Strom","c:d/d8/Dl650.jpg"],["Q1190076",185,"moto","Suzuki GS 500","C","La GS500 est une moto produite par le constructeur japonais Suzuki. C'est un roadster, qui se décline en deux versions: E pour la version non carénée, et F pour la version carénée.","La GS500 est une moto produite par le constructeur japonais Suzuki.","fr:Suzuki_GS_500","c:3/36/1997SuzukiGS500E-001.jpg"],["Q1124041",186,"moto","Suzuki GSX 1300R Hayabusa","PC","La GSX 1300 R Hayabusa est un modèle de moto du constructeur japonais Suzuki.",null,"fr:Suzuki_GSX_1300R_Hayabusa","c:5/5e/Hayabusa.jpg"],["Q1755865",187,"moto","Suzuki GSX-R 1000","PC","La Suzuki GSX-R1000 est une moto sportive lancée en 2001 avec un quatre-cylindres de 999 cm³. Elle est une référence des circuits et des championnats Superbike.","","en:Suzuki_GSX-R1000","c:2/26/Paris_Motor_Show_2018%2C_Paris_%281Y7A1508%29.jpg"],["Q1779147",188,"moto","Suzuki GSX-R 750","C","La Suzuki GSX-R 750 est un modèle de moto de 750 cm3 faisant partie de la catégorie des sportives construit par le fabricant japonais Suzuki.",114,"fr:Suzuki_GSX-R_750","c:5/51/GSX-R_750_1985_%26_GSX-R_750_R_1989.jpg"],["Q1423130",189,"moto","Suzuki SV 650","C","La Suzuki SV650 est une moto routière bicylindre produite depuis 1999, appréciée des débutants comme des motards confirmés.","","en:Suzuki_SV650","c:7/77/Suzuki_SV650.jpg"],["Q2096281",190,"moto","Triumph Bonneville","PC","La Bonneville, surnommée Bonnie, est un modèle de moto créé et commercialisé par la firme anglaise Triumph.",null,"fr:Triumph_Bonneville","c:6/62/ZweiRadMuseumNSU_Triumph_Bonneville.JPG"],["Q919987",191,"moto","Triumph Rocket III","C","La Rocket III est un modèle de moto custom construit par la firme britannique Triumph. Deux versions se sont succédé, la première est commercialisée de 2004 à 2017, et la seconde à partir de 2019, renommée Rocket 3.","La Rocket III est un modèle de moto custom construit par la firme britannique Triumph.","fr:Triumph_Rocket_III","c:7/7a/Rocket_3b.JPG"],["Q945184",192,"moto","Triumph Speed Triple","C","La Triumph Speed Triple est un roadster construit par la firme britannique Triumph.",null,"fr:Triumph_Speed_Triple","c:c/c8/Triumph_Speed_Triple_1200_RX.jpg"],["Q429893",193,"moto","Vespa 150 TAP","C","Le Vespa 150 TAP ou « Bazooka Vespa » est un scooter Vespa modifié pour transporter un canon sans recul M20 de 75 mm. Il a été utilisé à la fin des années 1950 et début des années 1960 par les troupes aéroportées françaises pendant la guerre d'Indochine par le Corps expéditionnaire français en Extrême-Orient et la guerre d'Algérie.","Le Vespa 150 TAP ou « Bazooka Vespa » est un scooter Vespa modifié pour transporter un canon sans recul M20 de 75 mm.","fr:Vespa_150_TAP","c:3/3e/Vespa_militare2.JPG"],["Q1319673",194,"moto","Welbike","C","La Welbike est une mini-moto pliante britannique de la Seconde Guerre mondiale, conçue pour être parachutée avec les commandos dans un container.","","en:Welbike","c:b/ba/Welbike.jpg"],["Q1332081",195,"moto","Yamaha Aerox","C","Le Yamaha Aerox est un scooter sportif produit depuis 1997, en 50 cm³ en Europe. C'est un classique des adolescents.","","en:Yamaha_Aerox","c:f/f3/Yamaha_Aerox_2011_.jpg"],["Q1190627",196,"moto","Yamaha FJR 1300","C","La FJR 1300 est un modèle de moto produit par le constructeur japonais Yamaha.",null,"fr:Yamaha_FJR_1300","c:4/41/Fjr1300.jpg"],["Q15199531",197,"moto","Yamaha MT-09","PC","La MT-09 est un modèle de moto du constructeur japonais Yamaha Motor inaugurant un nouveau moteur tricylindre. Sa dénomination « MT » pour « Master of Torque » la classe dans la lignée de la MT-01.","La MT-09 est un modèle de moto du constructeur japonais Yamaha Motor inaugurant un nouveau moteur tricylindre.","fr:Yamaha_MT-09","c:7/7f/2024_Yamaha_MT-09_Y-AMT.jpg"],["Q4405670",198,"moto","Yamaha Nouvo","C","La Yamaha Nouvo est un scooter à roues hautes lancé en 2002 pour l'Asie du Sud-Est. Son nom vient du mot français « nouveau ».","","en:Yamaha_Nouvo","c:c/ce/P6280061.JPG"],["Q589388",199,"moto","Yamaha TMAX","PC","Le XP 500 TMAX est un scooter fabriqué par Yamaha Motor. Sa commercialisation a commencé en Europe en 2001, région où la seconde génération a été introduite en 2008. Cette seconde génération a été mise à disposition sur le marché américain pour l'année-modèle 2009.","Le XP 500 TMAX est un scooter fabriqué par Yamaha Motor.","fr:Yamaha_TMAX","c:f/f0/2025_Yamaha_TMAX_560.jpg"],["Q1347870",200,"moto","Yamaha VMax","PC","La VMax est un modèle de motocyclette, construite par la firme japonaise Yamaha Motor Company.",null,"fr:Yamaha_VMax","c:2/2d/VMAX_day_2009_two_bikes_and_flags.jpg"],["Q937826",201,"moto","Yamaha YA-1","C","La Yamaha YA-1 est un modèle de motocyclette du constructeur japonais Yamaha Motor Company.",null,"fr:Yamaha_YA-1","c:9/9a/Yamaha_YA-1.jpg"],["Q1373162",202,"moto","Yamaha YBR 125","C","La YBR 125 est un modèle de motocyclette, de type roadster de Yamaha.",null,"fr:Yamaha_YBR_125","c:8/82/YBR125.JPG"],["Q604551",203,"moto","Yamaha YZF","R","La Yamaha YZF est une série de modèles de motos sportives produites par Yamaha Motor Company. La lignée des YZF débute en 1993 avec la 750. Elle se perpétue encore aujourd'hui.","La Yamaha YZF est une série de modèles de motos sportives produites par Yamaha Motor Company.","fr:Yamaha_YZF","c:5/51/2015_Yamaha_YZF-R1_crop.JPG"],["Q1462612",204,"moto","Yamaha YZF-R125","C","La Yamaha YZF-R125 est une moto sportive de 125 cm³ produite depuis 2008, petite sœur des R1 et R6.","","en:Yamaha_YZF-R125","c:9/90/Yamaha_YZF-R125_2025.jpg"],["Q1854043",205,"moto","Yamaha YZF-R6","PC","La Yamaha YZF-R6 est une moto sportive, produite par Yamaha dans la catégorie 600 de 1999 à 2020. À partir de 2021, la disponibilité de la production est limitée à une spécification non homologuée réservée à la compétition sur la plupart des marchés mondiaux, obligeant les organisateurs de courses à réaligner leurs critères d'éligibilité des moteurs afin d'encourager d'autres fabricants disposant de moteurs de plus de 600 cm3. Les cylindrées de cc qui entreront en compétition sur route à partir de 2022.","La Yamaha YZF-R6 est une moto sportive, produite par Yamaha dans la catégorie 600 de 1999 à 2020.","fr:Yamaha_YZF-R6","c:9/96/Peti_bardhal.jpg"],["Q302455",206,"moto","Yamaha YZR-M1","C","La Yamaha YZR-M1 est la moto de course développée par Yamaha pour le championnat MotoGP depuis 2002. Valentino Rossi a remporté plusieurs titres mondiaux à son guidon.","","en:Yamaha_YZR-M1","c:b/b2/MotoGP_2025_Malaysian_Grand_Prix_-_Monster_Energy_Yamaha_-_Fabio_Quartararo.jpg"],["Q622062",207,"marque","Aprilia","R","Aprilia est un constructeur italien de motos basé à Noale, près de Venise. Il fait partie du groupe italien Piaggio SpA depuis 2006.","Aprilia est un constructeur italien de motos basé à Noale, près de Venise.","fr:Aprilia","https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Aprilia-logo.svg/330px-Aprilia-logo.svg.png"],["Q249173",208,"marque","BMW Motorrad","PC","BMW Motorrad est la marque utilisée par le groupe industriel allemand BMW pour ses motos. La première moto BMW, la R 32, est construite en 1923: elle est déjà dotée d'un moteur bicylindre boxer à plat et d'une transmission par arbre caractéristiques de la marque. En cent ans d'existence, BMW est devenu le plus important fabricant occidental, avec une gamme de motos de moyenne et forte cylindrée qui s'est vendue à plus de 200 000 unités en 2022, générant un chiffre d'affaires de 3 176 M€.","BMW Motorrad est la marque utilisée par le groupe industriel allemand BMW pour ses motos.","fr:BMW_Motorrad","c:8/8d/1200gsfr.jpg"],["Q321785",209,"marque","Brabus","E","Brabus est un préparateur automobile allemand sur les modèles de série de Mercedes-Benz, Smart, Maybach mais également de Porsche et Rolls-Royce depuis 2022. L'entreprise est basée à Bottrop, aux environs de Düsseldorf en Allemagne. Ayant obtenu le statut de constructeur, ce qui le différencie des autres préparateurs, les véhicules Brabus ne sont pas badgés du logo Mercedes.",118,"fr:Brabus","c:5/58/Brabus_HQ.jpg"],["Q1025726",210,"marque","Cagiva","C","Cagiva est un constructeur italien de moto installé à Schiranna, commune de Varèse, dans la banlieue de Milan.",null,"fr:Cagiva","c:4/48/1995_Cagiva_Mito125_01.jpg"],["Q1199957",211,"marque","Derbi","C","Derbi est un constructeur de motos espagnol dont la société mère est italienne.",null,"fr:Derbi","c:a/a4/Derbi_GT_4V_2012_540.jpg"],["Q639268",212,"marque","DKW","PC","DKW est un ancien constructeur allemand d'automobiles et de motocyclettes fondée en 1917 par Jörgen Skafte Rasmussen, danois d'origine. Les usines étaient à Zwickau et le siège social à Zschopau, en Saxe.",117,"fr:DKW","https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/DKW-logo.svg/330px-DKW-logo.svg.png"],["Q745394",213,"marque","Gilera","C","Gilera est un fabricant de motos italien fondé à Arcore en 1909 par Giuseppe Gilera.",null,"fr:Gilera","https://upload.wikimedia.org/wikipedia/fr/thumb/2/2a/Logo-Gilera.svg/330px-Logo-Gilera.svg.png"],["Q13635788",214,"marque","Hennessey Performance Engineering","C","Hennessey Performance Engineering est une maison de tuning et un constructeur automobile américain spécialisé dans la modification de voitures de sport et de supercars de plusieurs marques dont Ferrari, Porsche, McLaren, Chevrolet, Dodge, Cadillac, Lotus, Jeep, Ford, GMC, Lincoln et Lexus. Maison fondée en 1991 par John Hennessey, son installation principale est située à 45 minutes à l'ouest de Houston, dans le Texas.",117,"fr:Hennessey_Performance_Engineering","c:f/ff/Cars_-_Hennessey_Venom_650R.jpg"],["Q1613763",215,"marque","Hero MotoCorp","R","Hero MotoCorp est un constructeur indien de motos et de scooters, basé à Delhi, en Inde. L'entreprise a été fondée en 1984 en tant que coentreprise entre Hero Cycles et Honda Motor Company. En 2010, Honda est sorti du capital de l'entreprise après avoir créé Honda Motorcycles and Scooters India. Hero Motocorp est actuellement le premier constructeur de deux-roues au monde.","Hero MotoCorp est un constructeur indien de motos et de scooters, basé à Delhi, en Inde.","fr:Hero_MotoCorp","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Hero_MotoCorp.svg/330px-Hero_MotoCorp.svg.png"],["Q5493297",216,"marque","Husqvarna Motorcycles","PC","Husqvarna Motorcycles est une entreprise d'origine suédoise, fondée en 1903 en tant que filiale du groupe Husqvarna. Elle conçoit et fabrique des motos dont des motocross.","Husqvarna Motorcycles est une entreprise d'origine suédoise, fondée en 1903 en tant que filiale du groupe Husqvarna.","fr:Husqvarna_Motorcycles","c:b/b1/R%C4%ABgas_motormuzejs_-_Husqvarna_500_%2809.09.2022%29.jpg"],["Q1091034",217,"marque","Indian","R","Indian est une des plus anciennes marques de motos dont le premier modèle, l'Indian Single, est lancé en 1901 par la société américaine Hendee Manufacturing Company de Springfield. HMC, numéro un des constructeurs de motos jusqu'à la Première Guerre mondiale, est l'un des deux seuls constructeurs américains à avoir survécu à la Grande Dépression du début des années 1930.",116,"fr:Indian","c:f/f7/SpringfieldMA_WinchesterSquare_IndianMotorcyclePlant.jpg"],["Q763622",218,"marque","Jawa","R","Jawa est une marque tchécoslovaque de motocyclettes créée en 1929. Son nom provient de la fusion de l'atelier de mécanique Janeček et de la division « motos » de Wanderer.","Jawa est une marque tchécoslovaque de motocyclettes créée en 1929.","fr:Jawa_(entreprise)","c:7/76/JAWA._Motorcycle_manufacturer.jpg"],["Q249033",219,"marque","Kawasaki Heavy Industries","PC","Kawasaki Heavy Industries, Ltd. est une multinationale japonaise spécialisée dans la fabrication de motos, d'équipements lourds, d'engins militaires, la construction aérospatiale, la construction ferroviaire et les chantiers navals. L'entreprise est également présente dans la robotique industrielle et le secteur de l'énergie.","Kawasaki Heavy Industries, Ltd.","fr:Kawasaki_Heavy_Industries_Motorcycle_&_Engine","c:b/bf/Kawasaki_Heavy_Industries.jpg"],["Q215657",220,"marque","KTM AG","E","KTM AG est un constructeur autrichien de motos dont l'établissement principal est situé à Mattighofen, au nord de Salzbourg. Ses origines remontent à 1934 avec la création d'une entreprise de mécanique par l'autrichien Hans Trunkenpolz. L'entreprise produit sa première moto en 1953 et devient célèbre pour ses motos tout-terrain à partir des années 1970. L'activité moto est reprise en 1992 par l'industriel Stefan Pierer qui en fait le plus important constructeur européen de motos au début des années 2020.",113,"fr:KTM_AG","c:1/1b/KTM_1290_Super_Adventure_R.jpg"],["Q696338",221,"marque","Kymco","C","Kymco ou Kwang Yang Motor Co, Ltd est un fabricant taïwanais de scooters, motos, quads et SSV pour le marché mondial. En Europe, ses modèles phares sont les scooters AK 550, Agility, K-XCT, X-Town, Downtown et Xciting, ainsi que la moto légère CK1 125. Kymco est très présent dans le secteur de la livraison en raison du caractère fiable, économique et du niveau de sécurité de ses scooters. En France, le fabricant équipe notamment La Poste et Domino's Pizza.","Kymco ou Kwang Yang Motor Co, Ltd est un fabricant taïwanais de scooters, motos, quads et SSV pour le marché mondial.","fr:Kymco","https://upload.wikimedia.org/wikipedia/fr/thumb/1/13/LOGO_KYMCO.svg/330px-LOGO_KYMCO.svg.png"],["Q1465351",222,"marque","Lifan","C","Lifan Motor Group est un groupe industriel chinois fondé en 1992, et établi à Chongqing. Il compte plus de 14 000 employés en 2008.","Lifan Motor Group est un groupe industriel chinois fondé en 1992, et établi à Chongqing.","fr:Lifan","c:c/c0/Lifan_Logo.jpg"],["Q1149018",223,"marque","Moto Guzzi","PC","Moto Guzzi est un constructeur de motos italien en activité sans interruption depuis sa création, en 1921, à Mandello del Lario près du lac de Côme. Moto Guzzi est le plus important fabricant italien de motos jusqu'aux années 1940 et remporte de très nombreux succès en compétition jusqu'à la fin des années 1950. Jusqu'à sa faillite en 1966, Guzzi a une offre très diversifiée: motos de petite, moyenne et grosse cylindrée, tricycles motorisés, engins agricoles, moteurs pour usages fixes, etc.",117,"fr:Moto_Guzzi","c:6/67/Moto_Guzzi_Symbol_noBG.png"],["Q1139995",224,"marque","MV Agusta","PC","MV Agusta est une marque de motos italienne créée en 1945 par Domenico Agusta à Verghera, une frazione de Samarate, dans la province de Varèse, dans le nord de la Lombardie. Le siège social de la société se trouve aujourd'hui à Varèse.",115,"fr:MV_Agusta","https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/MV_Agusta_Logo.svg/330px-MV_Agusta_Logo.svg.png"],["Q1150827",225,"marque","Norton Motorcycle Company","PC","Norton est une firme britannique de construction de motos, fondée par James Lansdowne Norton à Wolverhampton en 1898, puis transférée à Birmingham.",117,"fr:Norton_Motorcycle_Company","c:2/21/Ron_Haslam_on_a_Norton_motorcycle.jpg"],["Q39898",226,"marque","NSU Motorenwerke AG","R","NSU Motorenwerke AG est une entreprise allemande fondée en 1873 et spécialisée dans la fabrication de motocyclettes et d'automobiles.",118,"fr:NSU_Motorenwerke_AG","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/NSU_1960_Logo.svg/330px-NSU_1960_Logo.svg.png"],["Q1850587",227,"marque","Polaris","PC","Polaris Inc est un fabricant de motoneiges et de véhicules tout-terrain de type quad et de série Ranger, ainsi que de motos de marques Victory et Indian, cependant le groupe a renvendu cette dernière en février 2026. Son siège social est situé à Medina au Minnesota. Il est un pionnier dans le domaine du transport, étant la première entreprise à avoir produit commercialement des motoneiges, et demeure l'un des quatre fabricants dans le domaine, un marché de 200 000 véhicules annuellement.",117,"fr:Polaris_(entreprise)",""],["Q7334368",228,"marque","Rimac Automobili","E","Rimac Automobili est un constructeur automobile croate fondé en 2009 et spécialisé dans les voitures électriques. La société porte le nom de son fondateur, Mate Rimac. Elle est installée à Sveta Nedelja, près de Zagreb.","Rimac Automobili est un constructeur automobile croate fondé en 2009 et spécialisé dans les voitures électriques.","fr:Rimac_Automobili","c:8/8e/Rimac_C_Two_20180929_DSC_8816.jpg"],["Q2668720",229,"marque","Royal Enfield","L","Royal Enfield est un constructeur de motos indien basé à Chennai. Fondée en Angleterre, c'est la plus ancienne marque de motos encore en production, avec une première moto construite en 1901.","","en:Royal_Enfield","c:7/7a/4th_International_Auto_Show%2C_Bangalore_%282025%29_190.jpg"],["Q181642",230,"marque","Suzuki","L","Suzuki Motor Corporation est un groupe industriel japonais producteur d'automobiles, de motos et de moteurs hors-bord. Les origines de Suzuki remontent au début des années 1900 avec la création par Michio Suzuki d'une entreprise de machines pour l'industrie textile à Hamamatsu. À partir du milieu des années 1950, Suzuki se lance dans la construction de deux roues motorisés et d'automobiles, puis, à partir de 1965, de moteurs hors-bord.","Suzuki Motor Corporation est un groupe industriel japonais producteur d'automobiles, de motos et de moteurs hors-bord.","fr:Suzuki","c:9/92/Suzuki_Motor.jpg"],["Q1140383",231,"marque","Triumph","R","Triumph est une marque britannique de motos fondée par l'Allemand Siegfried Bettman en 1885. Elle appartient depuis 1983 à la société britannique Triumph Motorcycles Ltd, basée à Hinckley. Triumph est l'une des seules marques de motos à avoir été en activité sans interruption depuis le début du XXe siècle, avec plus d'un million de motos produites jusqu'à nos jours.","Triumph est une marque britannique de motos fondée par l'Allemand Siegfried Bettman en 1885.","fr:Triumph_(motos)","c:a/a3/1958_Triumph_T120_Bonneville_right_side.jpg"],["Q158888",232,"marque","Yamaha Motor Company","E","Yamaha Motor Co., Ltd. est un groupe industriel japonais constructeur de motos, scooters, moteurs marins et voiturettes de golf. Créé le 1er juillet 1955, il est séparé de Yamaha Corporation fondée en 1897 qui s’est imposée comme fabricant d’orgues et de pianos. Elle est connue sous le nom de « La maison des trois diapasons ».","Yamaha Motor Co., Ltd.","fr:Yamaha_Motor_Company","c:1/1c/YAMAHA_MT-09_Tracer%2C_photographed_in_Takurazaki%2C_October_2024_-_7956.jpg"],["Q59167",233,"marque","Zündapp","PC","Zündapp fut l'un des grands constructeurs allemands de motocyclettes de 1921 à 1984.",null,"fr:Zündapp","c:9/90/Z%C3%BCndapp-hp.jpg"],["Q891243",234,"competition","Bol d'or","C","Le Bol d'or est une compétition motocycliste d'endurance qui se déroule une fois par an en France.",null,"fr:Bol_d'or","https://upload.wikimedia.org/wikipedia/fr/thumb/4/45/Bol_d%27Or_Logo_1024x760.png/330px-Bol_d%27Or_Logo_1024x760.png",{"cats":["bolides","moto"]}],["Q1081023",235,"competition","Bonneville Salt Flats","R","Le Bonneville Salt Flats est une plaine de 260 km2 couverte de sel dans le nord-ouest de l'Utah, aux États-Unis, célèbre entre autres pour son circuit « Bonneville Speedway » de records de vitesse terrestre.",112,"fr:Bonneville_Salt_Flats","c:4/49/Bonneville_Salt_Flats_aerial_photo_Don_Ramey_Logan.jpg"],["Q3504613",236,"competition","Championnat AMA de supercross","C","Le Championnat AMA de supercross est le championnat national de supercross aux États-Unis et est actuellement la plus importante compétition de supercross dans le monde. Le championnat comporte environ 17 manches reparties sur plusieurs mois entre janvier et mai.",117,"fr:Championnat_AMA_de_supercross","c:e/e2/ManuRivas_AMASX2007.jpg",{"cats":["bolides","moto"]}],["Q845098",237,"competition","Championnat du monde de Superbike","R","Le championnat du monde de Superbike est la principale compétition de Superbike au niveau mondial, une catégorie de courses sur circuit de vitesse moto réservée aux motos de production. Le championnat a été créé en 1988. La saison du Championnat du monde de Superbike consiste en une série de courses qui se tiennent sur des circuits permanents. Chaque manche du championnat est composée de trois courses et le résultat permet de décerner à la fin de la saison le titre pilote et le titre constructeur.",115,"fr:Championnat_du_monde_de_Superbike","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Superbike_World_Championship_logo_%28stacked%2C_2022%29.svg/330px-Superbike_World_Championship_logo_%28stacked%2C_2022%29.svg.png",{"cats":["bolides","moto"]}],["Q850292",238,"competition","Championnats du monde de vitesse moto","L","Les Championnats du monde de vitesse moto regroupent les courses de motos sur circuit du niveau mondial en Grand Prix. Ils sont organisés sous l'égide de la Fédération internationale de motocyclisme. Contrairement aux autres championnats, toutes les machines en compétition sont des prototypes.","Les Championnats du monde de vitesse moto regroupent les courses de motos sur circuit du niveau mondial en Grand Prix.","fr:Championnats_du_monde_de_vitesse_moto","c:f/f3/Marc_M%C3%A1rquez_at_the_pit_lane_during_the_2025_Italian_motorcycle_Grand_Prix_%28front_view%2C_cropped%29.jpg",{"cats":["bolides","sports","moto"]}],["Q3054061",239,"competition","Enduropale","C","L'Enduropale, ou Enduropale du Touquet Pas-de-Calais, est une course motocycliste qui se déroule annuellement, en début d'année, depuis 1975 sur la Côte d'Opale, plus précisément sur les plages du Touquet-Paris-Plage et de Stella-Plage dans le Pas-de-Calais. Elle est aujourd'hui devenue la plus grande course d'enduro d'Europe et la plus longue course sur sable du monde avec ses quinze kilomètres.",119,"fr:Enduropale","c:4/4c/Le_Touquet-Paris-Plage_-_Enduropale_2022_-_Pilotes_motos_sur_la_ligne_de_d%C3%A9part_%281%29.jpg"],["Q376996",240,"competition","Grand Prix moto de France","C","Le Grand Prix moto de France de vitesse est une course motocycliste comptant pour les Championnats du monde de vitesse moto depuis 1951.",118,"fr:Grand_Prix_moto_de_France","https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Bugatti_Circuit.svg/330px-Bugatti_Circuit.svg.png"],["Q215862",241,"competition","Moto-cross","PC","Le moto-cross ou motocross est un sport extrême de compétition motocycliste consistant en une course de vitesse sur un circuit tout-terrain accidenté. La première course de moto-cross se déroula à Camberley dans le Surrey en 1924. Le sport connut ensuite un essor important en Grande-Bretagne, puis en Belgique et en France. Il gagna peu à peu l’Europe centrale puis les États-Unis où il a attiré un nombre croissant de pratiquants.",118,"fr:Moto-cross","c:9/9e/Motocross_MX_green.jpg"],["Q181336",242,"competition","Rallye Dakar","L","Le Rallye Dakar est un rallye-raid marathon, créé par Thierry Sabine et lancé pour la première fois en décembre 1978. Depuis lors, il a été disputé chaque année, sauf en 2008, entre la fin décembre et la mi-janvier sur une durée de deux à trois semaines. Initialement disputé en partie en Europe et majoritairement en Afrique, l'épreuve se déroule en Amérique du Sud de 2009 à 2019 puis en Arabie saoudite à partir de 2020.","Le Rallye Dakar est un rallye-raid marathon, créé par Thierry Sabine et lancé pour la première fois en décembre 1978.","fr:Rallye_Dakar","https://upload.wikimedia.org/wikipedia/fr/thumb/b/bf/Logo_rallye_Dakar.svg/330px-Logo_rallye_Dakar.svg.png",{"cats":["bolides","sports","moto"]}],["Q522661",243,"competition","Tourist Trophy de l'île de Man","E","Le Tourist Trophy de l'île de Man ou Tourist Trophy est un événement motocycliste annuel de course sur route, créé en 1907, qui se déroule sur l'île de Man pendant deux semaines fin mai-début juin. Les courses se déroulent par catégories définies en fonction de la cylindrée et de la motorisation. Épreuve du championnat du monde de vitesse moto depuis sa création en 1949, elle est retirée du calendrier par la FIM en 1976 ne répondant plus aux attentes des Grands Prix moto.",117,"fr:Tourist_Trophy_de_l'île_de_Man","https://upload.wikimedia.org/wikipedia/fr/thumb/4/45/Isle_of_Man_TT.svg/330px-Isle_of_Man_TT.svg.png",{"cats":["bolides","moto"]}]]]);